def run_backup_retention_apply_draft_preview(args: argparse.Namespace) -> dict[str, Any]:
    warnings: list[dict[str, Any]] = []
    errors = _backup_retention_apply_config_errors(args)
    inputs = _backup_retention_apply_inputs(args)
    preview_report, preview_errors = _load_backup_retention_apply_required_report(
        inputs["preview"],
        expected_mode="backup-retention-preview",
    )
    rotation_report, rotation_errors = _load_backup_retention_apply_required_report(
        inputs["rotation_plan"],
        expected_mode="backup-retention-rotation-plan-preview",
    )
    errors.extend(preview_errors)
    errors.extend(rotation_errors)
    inventory_report = _load_backup_retention_apply_inventory(inputs["inventory"], warnings=warnings)
    rotation_rows = list(rotation_report.get("rotation_plan_rows") or [])
    inventory_by_path = {
        str(row.get("path") or ""): row
        for row in inventory_report.get("inventory_rows") or []
        if str(row.get("path") or "")
    }
    artifacts = _backup_retention_apply_artifacts(args)
    errors.extend(
        _backup_retention_apply_output_errors(
            args,
            inputs=inputs,
            artifacts=artifacts,
            rotation_rows=rotation_rows,
        )
    )
    snapshots = _backup_retention_apply_snapshots(inputs)
    apply_rows = [
        _build_backup_retention_apply_row(
            args,
            row,
            inventory_by_path=inventory_by_path,
            preview_status=str(preview_report.get("status") or ""),
        )
        for row in rotation_rows
    ]
    _apply_backup_retention_apply_limits(args, apply_rows=apply_rows)
    manifest_rows = _build_backup_retention_cleanup_manifest_rows(apply_rows)
    blocker_rows = _build_backup_retention_apply_blocker_rows(apply_rows)
    if manifest_rows and args.backup_retention_require_manual_review:
        warnings.append({"message": "backup_retention_apply_manual_review_pending"})
    if blocker_rows:
        warnings.append({"message": "backup_retention_apply_blockers_present"})
    if not errors and artifacts["cleanup_script"] is not None:
        try:
            _write_backup_retention_cleanup_script(manifest_rows, artifacts["cleanup_script"])
            try:
                os.chmod(artifacts["cleanup_script"], 0o644)
            except OSError:
                warnings.append({"message": "backup_retention_cleanup_script_chmod_unavailable"})
        except OSError as exc:
            errors.append({"message": str(exc)})
    if not _backup_retention_apply_snapshots_unchanged(snapshots):
        errors.append({"message": "backup_retention_apply_input_changed"})
    report = _build_backup_retention_apply_report(
        args,
        preview_report=preview_report,
        rotation_rows=rotation_rows,
        apply_rows=apply_rows,
        blocker_rows=blocker_rows,
        manifest_rows=manifest_rows,
        artifacts=artifacts,
        warnings=warnings,
        errors=errors,
    )
    if not errors:
        try:
            if artifacts["apply_json"] is not None:
                write_json_report(report, artifacts["apply_json"])
            if artifacts["apply_csv"] is not None:
                _write_flat_csv(apply_rows, BACKUP_RETENTION_APPLY_FIELDS, artifacts["apply_csv"])
            if artifacts["apply_markdown"] is not None:
                write_backup_retention_apply_markdown(report, artifacts["apply_markdown"])
            if artifacts["blockers_json"] is not None:
                write_json_report(_backup_retention_apply_blockers_report(report), artifacts["blockers_json"])
            if artifacts["blockers_csv"] is not None:
                _write_flat_csv(blocker_rows, BACKUP_RETENTION_APPLY_BLOCKER_FIELDS, artifacts["blockers_csv"])
            if artifacts["manifest_json"] is not None:
                write_json_report(_backup_retention_cleanup_manifest_report(report), artifacts["manifest_json"])
            if artifacts["manifest_csv"] is not None:
                _write_flat_csv(manifest_rows, BACKUP_RETENTION_CLEANUP_MANIFEST_FIELDS, artifacts["manifest_csv"])
        except OSError as exc:
            report["status"] = "failed"
            report["errors"] = [*report["errors"], {"message": str(exc)}]
    return report


def _backup_retention_apply_inputs(args: argparse.Namespace) -> dict[str, Path | None]:
    output_dir = args.operator_resolution_chain_output_dir
    return {
        "preview": args.backup_retention_preview_input
        or (output_dir / BACKUP_RETENTION_ARTIFACT_NAMES["preview_json"] if output_dir else None),
        "rotation_plan": args.backup_retention_rotation_plan_input
        or (output_dir / BACKUP_RETENTION_ARTIFACT_NAMES["rotation_plan_json"] if output_dir else None),
        "inventory": args.backup_retention_inventory_input
        or (output_dir / BACKUP_RETENTION_ARTIFACT_NAMES["inventory_json"] if output_dir else None),
    }


def _backup_retention_apply_artifacts(args: argparse.Namespace) -> dict[str, Path | None]:
    output_dir = args.operator_resolution_chain_output_dir
    overrides = {
        "apply_json": args.backup_retention_apply_output,
        "apply_csv": args.backup_retention_apply_csv_output,
        "apply_markdown": args.backup_retention_apply_markdown_output,
        "blockers_json": args.backup_retention_apply_blockers_output,
        "blockers_csv": args.backup_retention_apply_blockers_csv_output,
        "cleanup_script": args.backup_retention_cleanup_script_output,
        "manifest_json": args.backup_retention_cleanup_manifest_output,
        "manifest_csv": args.backup_retention_cleanup_manifest_csv_output,
    }
    return {
        key: overrides[key] or (output_dir / file_name if output_dir is not None else None)
        for key, file_name in BACKUP_RETENTION_APPLY_ARTIFACT_NAMES.items()
    }


def _backup_retention_apply_config_errors(args: argparse.Namespace) -> list[dict[str, Any]]:
    errors: list[dict[str, Any]] = []
    if args.backup_retention_max_delete_count < 0:
        errors.append({"message": "invalid_backup_retention_apply_policy_value:backup_retention_max_delete_count"})
    if args.backup_retention_max_delete_gb < 0:
        errors.append({"message": "invalid_backup_retention_apply_policy_value:backup_retention_max_delete_gb"})
    if not _backup_retention_backups_dir_is_safe(args.backup_retention_backups_dir):
        errors.append({"message": "backup_retention_backups_dir_unsafe"})
    return errors


def _load_backup_retention_apply_required_report(
    path: Path | None,
    *,
    expected_mode: str,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    if path is None or not path.is_file():
        return {}, [{"message": "backup_retention_apply_preview_input_required"}]
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}, [{"message": "backup_retention_apply_preview_input_invalid", "path": str(path)}]
    if not isinstance(payload, dict) or payload.get("mode") != expected_mode:
        return {}, [{"message": "backup_retention_apply_preview_input_invalid", "path": str(path)}]
    if expected_mode == "backup-retention-rotation-plan-preview" and not isinstance(
        payload.get("rotation_plan_rows"), list
    ):
        return {}, [{"message": "backup_retention_apply_preview_input_invalid", "path": str(path)}]
    if expected_mode == "backup-retention-rotation-plan-preview" and not all(
        isinstance(row, dict) for row in payload.get("rotation_plan_rows") or []
    ):
        return {}, [{"message": "backup_retention_apply_preview_input_invalid", "path": str(path)}]
    return payload, []


def _load_backup_retention_apply_inventory(
    path: Path | None,
    *,
    warnings: list[dict[str, Any]],
) -> dict[str, Any]:
    if path is None or not path.is_file():
        warnings.append({"message": "backup_retention_apply_inventory_input_missing"})
        return {}
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        warnings.append({"message": "backup_retention_apply_inventory_input_unreadable", "path": str(path)})
        return {}
    if (
        not isinstance(payload, dict)
        or payload.get("mode") != "backup-retention-inventory-preview"
        or not isinstance(payload.get("inventory_rows"), list)
        or not all(isinstance(row, dict) for row in payload.get("inventory_rows") or [])
    ):
        warnings.append({"message": "backup_retention_apply_inventory_input_unreadable", "path": str(path)})
        return {}
    return payload


def _backup_retention_apply_output_errors(
    args: argparse.Namespace,
    *,
    inputs: dict[str, Path | None],
    artifacts: dict[str, Path | None],
    rotation_rows: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    outputs = [path for path in [*artifacts.values(), args.json_output, args.markdown_output] if path is not None]
    protected = [
        path
        for path in [
            *inputs.values(),
            args.backup_retention_backups_dir,
            *(Path(str(row.get("path") or "")) for row in rotation_rows if str(row.get("path") or "")),
        ]
        if path is not None
    ]
    for index, output in enumerate(outputs):
        if any(_paths_equal(output, other) for other in outputs[index + 1 :]):
            return [{"message": "backup_retention_apply_output_must_not_equal_input"}]
        if any(_paths_equal(output, path) for path in protected):
            return [{"message": "backup_retention_apply_output_must_not_equal_input"}]
        if _path_is_within(output, args.backup_retention_backups_dir):
            return [{"message": "backup_retention_apply_output_must_not_equal_input"}]
    return []


def _backup_retention_apply_snapshots(inputs: dict[str, Path | None]) -> dict[Path, bytes]:
    return {
        path: path.read_bytes()
        for path in inputs.values()
        if path is not None and path.is_file()
    }


def _backup_retention_apply_snapshots_unchanged(snapshots: dict[Path, bytes]) -> bool:
    try:
        return all(path.is_file() and path.read_bytes() == content for path, content in snapshots.items())
    except OSError:
        return False


def _build_backup_retention_apply_row(
    args: argparse.Namespace,
    row: dict[str, Any],
    *,
    inventory_by_path: dict[str, dict[str, Any]],
    preview_status: str,
) -> dict[str, Any]:
    path = Path(str(row.get("path") or ""))
    inventory = inventory_by_path.get(str(row.get("path") or "")) or {}
    rotation_action = str(row.get("rotation_action") or "")
    protection_reasons = _financial_document_fetch_list(row.get("protection_reasons"))
    extension = _backup_retention_recognized_extension(path.name)
    direct_child = _backup_retention_apply_path_inside_backups_dir(path, args.backup_retention_backups_dir)
    is_symlink = path.is_symlink()
    exists = path.exists()
    is_regular = exists and path.is_file() and not is_symlink
    current_size: int | None = None
    current_mtime = ""
    current_mtime_timestamp: float | None = None
    if is_regular:
        try:
            stat = path.stat()
            current_size = stat.st_size
            current_mtime_timestamp = stat.st_mtime
            current_mtime = _timestamp_to_utc_iso(stat.st_mtime)
        except OSError:
            is_regular = False
    cleanup_line = f"# rm -- {_bash_quote(str(path))}"
    apply = {
        "apply_id": f"backup_retention_apply:{row.get('rotation_plan_id') or hashlib.sha256(str(path).encode('utf-8')).hexdigest()}",
        "rotation_plan_id": str(row.get("rotation_plan_id") or ""),
        "inventory_id": str(inventory.get("inventory_id") or ""),
        "file_name": path.name,
        "file_path": str(path),
        "recognized_backup_file": bool(row.get("recognized_backup")),
        "file_extension": extension,
        "task138_size_bytes": _as_int(row.get("size_bytes")),
        "current_size_bytes": current_size,
        "task138_mtime_utc": str(row.get("mtime_utc") or ""),
        "current_mtime_utc": current_mtime,
        "current_mtime_timestamp": current_mtime_timestamp,
        "file_exists_now": exists,
        "is_regular_file_now": is_regular,
        "is_symlink_now": is_symlink,
        "path_inside_backups_dir": direct_child,
        "rotation_action": rotation_action,
        "task138_rotation_reason": str(row.get("rotation_reason") or ""),
        "apply_status": "",
        "apply_severity": "",
        "apply_action": "",
        "apply_reason_codes": [],
        "apply_errors": [],
        "apply_warnings": [],
        "protected_by_latest_count": "keep_latest" in protection_reasons,
        "protected_by_daily_policy": "keep_daily" in protection_reasons,
        "protected_by_weekly_policy": "keep_weekly" in protection_reasons,
        "protected_by_extension_policy": not bool(extension),
        "eligible_for_future_manual_delete": False,
        "requires_manual_review": args.backup_retention_require_manual_review,
        "manual_review_status": (
            "required_pending_manual_review"
            if args.backup_retention_require_manual_review
            else "not_required_by_configuration_preview_only"
        ),
        "cleanup_script_line": cleanup_line,
        "cleanup_script_line_enabled": False,
        "cleanup_script_line_comment": "Candidate command remains commented after mandatory exit 0.",
        "would_delete_file": False,
        "would_move_file": False,
        "would_compress_file": False,
        "would_upload_file": False,
        "would_mutate_database": False,
    }
    status, reason = _classify_backup_retention_apply_row(args, apply, preview_status=preview_status)
    _set_backup_retention_apply_status(apply, status=status, reason=reason)
    return apply


def _classify_backup_retention_apply_row(
    args: argparse.Namespace,
    row: dict[str, Any],
    *,
    preview_status: str,
) -> tuple[str, str]:
    if not _backup_retention_apply_preview_status_allowed(args.backup_retention_require_preview_status, preview_status):
        return "blocked_preview_status_not_allowed", "preview_status_not_allowed"
    if not row["path_inside_backups_dir"]:
        return "blocked_unsafe_path", "unsafe_path"
    if row["is_symlink_now"]:
        return "blocked_symlink", "symlink_not_allowed"
    if row["rotation_action"] == "candidate_manual_review_unknown_file":
        return "skipped_unknown_file_manual_review", "unknown_file_manual_review"
    if row["rotation_action"] != "candidate_delete_old_backup":
        if row["rotation_action"] in {"", "none", "preview_noop"}:
            return "skipped_not_rotation_candidate", "not_rotation_candidate"
        return "blocked_invalid_rotation_action", "invalid_rotation_action"
    if not row["file_exists_now"]:
        return "skipped_file_missing", "file_missing"
    if not row["is_regular_file_now"]:
        return "blocked_unknown_readiness", "file_not_regular"
    if row["protected_by_extension_policy"] or not row["recognized_backup_file"]:
        return "skipped_unknown_file_manual_review", "unknown_file_manual_review"
    if (
        row["protected_by_latest_count"]
        or row["protected_by_daily_policy"]
        or row["protected_by_weekly_policy"]
    ):
        return "blocked_protected_by_policy", "protected_by_retention_policy"
    if row["task138_size_bytes"] != row["current_size_bytes"]:
        return "skipped_file_drift_detected", "file_size_drift"
    task138_mtime = _parse_utc_timestamp(row["task138_mtime_utc"])
    if (
        task138_mtime is None
        or row["current_mtime_timestamp"] is None
        or abs(float(row["current_mtime_timestamp"]) - task138_mtime) > 1.0
    ):
        return "skipped_file_drift_detected", "file_mtime_drift"
    return "eligible_manual_delete_preview", ""


def _backup_retention_apply_preview_status_allowed(required: str, actual: str) -> bool:
    return actual == "passed" if required == "passed" else actual in {"passed", "warning"}


def _backup_retention_apply_path_inside_backups_dir(path: Path, backups_dir: Path) -> bool:
    try:
        return path.absolute().parent.resolve() == backups_dir.resolve()
    except OSError:
        return False


def _parse_utc_timestamp(value: Any) -> float | None:
    try:
        return datetime.fromisoformat(str(value).replace("Z", "+00:00")).timestamp()
    except (TypeError, ValueError):
        return None


def _set_backup_retention_apply_status(row: dict[str, Any], *, status: str, reason: str) -> None:
    row["apply_status"] = status
    row["apply_reason_codes"] = [reason] if reason else []
    row["apply_severity"] = "info" if status == "eligible_manual_delete_preview" else "warning"
    row["apply_action"] = "include_in_cleanup_manifest_preview" if status == "eligible_manual_delete_preview" else "skip"
    row["eligible_for_future_manual_delete"] = status == "eligible_manual_delete_preview"


def _apply_backup_retention_apply_limits(args: argparse.Namespace, *, apply_rows: list[dict[str, Any]]) -> None:
    candidates = sorted(
        (row for row in apply_rows if row["apply_status"] == "eligible_manual_delete_preview"),
        key=lambda row: (row["current_mtime_timestamp"] or 0, row["file_path"]),
    )
    accepted_count = 0
    accepted_bytes = 0
    max_bytes = args.backup_retention_max_delete_gb * (1024**3)
    for row in candidates:
        size_bytes = int(row["current_size_bytes"] or 0)
        if accepted_count >= args.backup_retention_max_delete_count:
            _set_backup_retention_apply_status(
                row,
                status="blocked_delete_limit_exceeded",
                reason="delete_count_limit_exceeded",
            )
            continue
        if accepted_bytes + size_bytes > max_bytes:
            _set_backup_retention_apply_status(
                row,
                status="blocked_reclaim_limit_exceeded",
                reason="reclaim_size_limit_exceeded",
            )
            continue
        accepted_count += 1
        accepted_bytes += size_bytes


def _build_backup_retention_cleanup_manifest_rows(apply_rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    eligible = sorted(
        (row for row in apply_rows if row["apply_status"] == "eligible_manual_delete_preview"),
        key=lambda row: (row["current_mtime_timestamp"] or 0, row["file_path"]),
    )
    return [
        {
            "manifest_id": f"backup_retention_cleanup_manifest:{row['apply_id']}",
            "apply_id": row["apply_id"],
            "file_name": row["file_name"],
            "file_path": row["file_path"],
            "size_bytes": row["current_size_bytes"],
            "size_mb": _bytes_to_mb(int(row["current_size_bytes"] or 0)),
            "size_gb": _bytes_to_gb(int(row["current_size_bytes"] or 0)),
            "mtime_utc": row["current_mtime_utc"],
            "sha256_optional": "not_calculated_preview_only",
            "eligible_for_future_manual_delete": True,
            "manual_review_required": row["requires_manual_review"],
            "cleanup_script_line": row["cleanup_script_line"],
            "cleanup_script_line_enabled": False,
            "would_delete_file": False,
        }
        for row in eligible
    ]


def _build_backup_retention_apply_blocker_rows(apply_rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return [
        {
            "blocker_id": f"backup_retention_apply_blocker:{row['apply_id']}:{reason}",
            "apply_id": row["apply_id"],
            "rotation_plan_id": row["rotation_plan_id"],
            "file_name": row["file_name"],
            "file_path": row["file_path"],
            "apply_status": row["apply_status"],
            "blocker_code": reason,
            "severity": row["apply_severity"],
            "next_manual_action": "Review the Task139 blocker before any future explicit manual cleanup.",
            "would_delete_file": False,
        }
        for row in apply_rows
        if row["apply_status"] != "eligible_manual_delete_preview"
        for reason in (row["apply_reason_codes"] or ["unknown_readiness"])
    ]


def _write_backup_retention_cleanup_script(rows: list[dict[str, Any]], path: Path) -> None:
    lines = [
        "#!/usr/bin/env bash",
        "set -euo pipefail",
        "",
        'echo "Backup retention cleanup preview only. No deletion commands are enabled."',
        'echo "Review Task139 manifest before any manual cleanup."',
        "exit 0",
        "",
    ]
    for row in rows:
        lines.extend(["# Candidate after manual review:", row["cleanup_script_line"], ""])
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("\n".join(lines), encoding="utf-8")


def _build_backup_retention_apply_report(
    args: argparse.Namespace,
    *,
    preview_report: dict[str, Any],
    rotation_rows: list[dict[str, Any]],
    apply_rows: list[dict[str, Any]],
    blocker_rows: list[dict[str, Any]],
    manifest_rows: list[dict[str, Any]],
    artifacts: dict[str, Path | None],
    warnings: list[dict[str, Any]],
    errors: list[dict[str, Any]],
) -> dict[str, Any]:
    warnings = _dedupe_messages(warnings)
    status_counts = _count_values(apply_rows, "apply_status")
    blocker_counts = _count_values(blocker_rows, "blocker_code")
    reclaimable_bytes = sum(int(row["size_bytes"] or 0) for row in manifest_rows)
    status = "failed" if errors else "warning" if warnings or blocker_rows else "passed"
    return {
        "status": status,
        "mode": "backup-retention-apply-draft-preview",
        "backups_dir": str(args.backup_retention_backups_dir),
        "task138_preview_status": preview_report.get("status"),
        "rotation_plan_input_count": len(rotation_rows),
        "apply_row_count": len(apply_rows),
        "eligible_manual_delete_preview_count": len(manifest_rows),
        "skipped_count": sum(row["apply_status"].startswith("skipped_") for row in apply_rows),
        "blocked_count": sum(row["apply_status"].startswith("blocked_") for row in apply_rows),
        "failed_count": sum(row["apply_status"].startswith("failed_") for row in apply_rows),
        "manifest_row_count": len(manifest_rows),
        "estimated_reclaimable_bytes": reclaimable_bytes,
        "estimated_reclaimable_gb": _bytes_to_gb(reclaimable_bytes),
        "max_delete_count": args.backup_retention_max_delete_count,
        "max_delete_gb": args.backup_retention_max_delete_gb,
        "require_preview_status": args.backup_retention_require_preview_status,
        "require_manual_review": args.backup_retention_require_manual_review,
        "apply_status_counts": status_counts,
        "blocker_code_counts": blocker_counts,
        "apply_rows": apply_rows,
        "blocker_rows": blocker_rows,
        "cleanup_manifest_rows": manifest_rows,
        "artifacts": {key: _path_value(path) for key, path in artifacts.items()},
        "warnings": warnings,
        "errors": errors,
        "next_steps": _next_steps("backup-retention-apply-draft-preview", status),
        **_backup_retention_safety_flags(),
    }


def _backup_retention_apply_blockers_report(report: dict[str, Any]) -> dict[str, Any]:
    return {
        "status": report["status"],
        "mode": "backup-retention-apply-blockers-preview",
        "blocker_row_count": len(report["blocker_rows"]),
        "blocker_code_counts": report["blocker_code_counts"],
        "blocker_rows": report["blocker_rows"],
        **_backup_retention_safety_flags(),
    }


def _backup_retention_cleanup_manifest_report(report: dict[str, Any]) -> dict[str, Any]:
    return {
        "status": report["status"],
        "mode": "backup-retention-cleanup-manifest-preview",
        "manifest_row_count": report["manifest_row_count"],
        "estimated_reclaimable_bytes": report["estimated_reclaimable_bytes"],
        "estimated_reclaimable_gb": report["estimated_reclaimable_gb"],
        "cleanup_manifest_rows": report["cleanup_manifest_rows"],
        **_backup_retention_safety_flags(),
    }


def run_backup_retention_controlled_apply(args: argparse.Namespace) -> dict[str, Any]:
    warnings: list[dict[str, Any]] = []
    errors = _backup_retention_controlled_apply_config_errors(args)
    inputs = _backup_retention_controlled_apply_inputs(args)
    manifest_report, manifest_bytes, manifest_errors = _load_backup_retention_controlled_apply_manifest(
        inputs["manifest"]
    )
    errors.extend(manifest_errors)
    apply_report = _load_backup_retention_controlled_apply_optional_report(
        inputs["apply"],
        expected_mode="backup-retention-apply-draft-preview",
        rows_field="apply_rows",
        role="apply_preview",
        warnings=warnings,
    )
    task139_blocker_report = _load_backup_retention_controlled_apply_optional_report(
        inputs["blockers"],
        expected_mode="backup-retention-apply-blockers-preview",
        rows_field="blocker_rows",
        role="apply_blockers",
        warnings=warnings,
    )
    manifest_rows = list(manifest_report.get("cleanup_manifest_rows") or [])
    artifacts = _backup_retention_controlled_apply_artifacts(args)
    errors.extend(
        _backup_retention_controlled_apply_output_errors(
            args,
            inputs=inputs,
            artifacts=artifacts,
            manifest_rows=manifest_rows,
        )
    )
    if args.backup_retention_execute and artifacts["ledger_json"] is None:
        errors.append({"message": "backup_retention_deletion_ledger_output_required_for_execute"})
    snapshots = _backup_retention_apply_snapshots(inputs)
    cleanup_manifest_sha256 = hashlib.sha256(manifest_bytes).hexdigest() if manifest_bytes else ""
    confirmation_token_expected = (
        f"CONFIRM_BACKUP_DELETE_TASK139_{cleanup_manifest_sha256[:12]}_{len(manifest_rows)}"
        if cleanup_manifest_sha256
        else ""
    )
    confirmation_token_matches = bool(
        args.backup_retention_confirmation_token
        and args.backup_retention_confirmation_token == confirmation_token_expected
    )
    expected_manifest_sha256_matches = bool(
        args.backup_retention_expected_manifest_sha256
        and args.backup_retention_expected_manifest_sha256 == cleanup_manifest_sha256
    )
    global_block_status, global_block_reason = _backup_retention_controlled_apply_global_block(
        args,
        confirmation_token_matches=confirmation_token_matches,
        expected_manifest_sha256_matches=expected_manifest_sha256_matches,
    )
    deletion_execution_enabled = bool(args.backup_retention_execute and not global_block_status and not errors)
    task139_apply_by_id = _group_rows_by_field(apply_report.get("apply_rows") or [], "apply_id")
    task139_blockers_by_id = _group_rows_by_field(task139_blocker_report.get("blocker_rows") or [], "apply_id")
    controlled_apply_rows = [
        _build_backup_retention_controlled_apply_row(
            args,
            row,
            task139_apply_by_id=task139_apply_by_id,
            task139_blockers_by_id=task139_blockers_by_id,
            deletion_execution_enabled=deletion_execution_enabled,
            confirmation_token_matches=confirmation_token_matches,
            expected_manifest_sha256_matches=expected_manifest_sha256_matches,
        )
        for row in manifest_rows
    ]
    _apply_backup_retention_controlled_apply_limits(args, rows=controlled_apply_rows)
    for row in controlled_apply_rows:
        if row["controlled_apply_status"]:
            continue
        if not args.backup_retention_execute:
            _set_backup_retention_controlled_apply_status(
                row,
                status="dry_run_eligible_for_delete",
                reason="",
            )
        elif global_block_status:
            _set_backup_retention_controlled_apply_status(
                row,
                status=global_block_status,
                reason=global_block_reason,
            )
    cleanup_attempted = False
    if deletion_execution_enabled:
        ledger_rows = _build_backup_retention_deletion_ledger_rows(controlled_apply_rows)
        try:
            _persist_backup_retention_controlled_apply_ledger(
                ledger_rows,
                json_path=artifacts["ledger_json"],
                csv_path=artifacts["ledger_csv"],
                safety_flags=_backup_retention_controlled_apply_safety_flags(
                    execute_requested=True,
                    cleanup_attempted=False,
                    deleted_count=0,
                    estimated_reclaimable_bytes=_backup_retention_controlled_apply_estimated_bytes(
                        controlled_apply_rows
                    ),
                ),
            )
        except OSError as exc:
            errors.append({"message": "backup_retention_controlled_apply_ledger_write_failed", "error": str(exc)})
            deletion_execution_enabled = False
    if deletion_execution_enabled:
        aborted = False
        for row in controlled_apply_rows:
            if row["controlled_apply_status"]:
                continue
            if aborted:
                _set_backup_retention_controlled_apply_status(
                    row,
                    status="blocked_execution_aborted_after_delete_exception",
                    reason="execution_aborted_after_delete_exception",
                )
                continue
            if not _backup_retention_controlled_apply_manifest_unchanged(inputs["manifest"], manifest_bytes):
                _set_backup_retention_controlled_apply_status(
                    row,
                    status="blocked_file_drift_detected",
                    reason="cleanup_manifest_changed_after_preflight",
                )
                aborted = True
                continue
            fresh_status, fresh_reason = _revalidate_backup_retention_controlled_apply_row(
                row,
                backups_dir=args.backup_retention_backups_dir,
            )
            if fresh_status:
                _set_backup_retention_controlled_apply_status(row, status=fresh_status, reason=fresh_reason)
                continue
            cleanup_attempted = True
            row["controlled_apply_action"] = "delete_backup_file_after_all_guards"
            row["ledger_status"] = "delete_attempt_pending"
            ledger_rows = _build_backup_retention_deletion_ledger_rows(controlled_apply_rows)
            try:
                _persist_backup_retention_controlled_apply_ledger(
                    ledger_rows,
                    json_path=artifacts["ledger_json"],
                    csv_path=artifacts["ledger_csv"],
                    safety_flags=_backup_retention_controlled_apply_safety_flags(
                        execute_requested=True,
                        cleanup_attempted=True,
                        deleted_count=sum(bool(item["did_delete_file"]) for item in controlled_apply_rows),
                        estimated_reclaimable_bytes=_backup_retention_controlled_apply_estimated_bytes(
                            controlled_apply_rows
                        ),
                    ),
                )
                _delete_backup_file_after_all_guards(
                    args,
                    row,
                    confirmation_token_matches=confirmation_token_matches,
                    expected_manifest_sha256_matches=expected_manifest_sha256_matches,
                )
                row["file_exists_after"] = Path(row["file_path"]).exists()
                if row["file_exists_after"]:
                    raise OSError("backup file still exists after guarded unlink")
                row["did_delete_file"] = True
                _set_backup_retention_controlled_apply_status(row, status="deleted", reason="")
            except (OSError, RuntimeError) as exc:
                row["delete_exception"] = str(exc)
                row["controlled_apply_errors"] = [str(exc)]
                _set_backup_retention_controlled_apply_status(
                    row,
                    status="failed_delete_exception",
                    reason="delete_exception",
                )
                aborted = True
            ledger_rows = _build_backup_retention_deletion_ledger_rows(controlled_apply_rows)
            try:
                _persist_backup_retention_controlled_apply_ledger(
                    ledger_rows,
                    json_path=artifacts["ledger_json"],
                    csv_path=artifacts["ledger_csv"],
                    safety_flags=_backup_retention_controlled_apply_safety_flags(
                        execute_requested=True,
                        cleanup_attempted=cleanup_attempted,
                        deleted_count=sum(bool(item["did_delete_file"]) for item in controlled_apply_rows),
                        estimated_reclaimable_bytes=_backup_retention_controlled_apply_estimated_bytes(
                            controlled_apply_rows
                        ),
                    ),
                )
            except OSError as exc:
                errors.append({"message": "backup_retention_controlled_apply_ledger_write_failed", "error": str(exc)})
                aborted = True
        if aborted:
            for row in controlled_apply_rows:
                if not row["controlled_apply_status"]:
                    _set_backup_retention_controlled_apply_status(
                        row,
                        status="blocked_execution_aborted_after_delete_exception",
                        reason="execution_aborted_after_delete_exception",
                    )
    if not _backup_retention_apply_snapshots_unchanged(snapshots):
        errors.append({"message": "backup_retention_controlled_apply_input_changed"})
    snapshot_rows, snapshot_warnings = _scan_backup_retention_controlled_apply_snapshot(
        args.backup_retention_backups_dir
    )
    warnings.extend(snapshot_warnings)
    blocker_rows = _build_backup_retention_controlled_apply_blocker_rows(
        controlled_apply_rows,
        task139_blocker_rows=task139_blocker_report.get("blocker_rows") or [],
    )
    ledger_rows = _build_backup_retention_deletion_ledger_rows(controlled_apply_rows)
    report = _build_backup_retention_controlled_apply_report(
        args,
        controlled_apply_rows=controlled_apply_rows,
        blocker_rows=blocker_rows,
        ledger_rows=ledger_rows,
        snapshot_rows=snapshot_rows,
        artifacts=artifacts,
        manifest_rows=manifest_rows,
        cleanup_manifest_sha256=cleanup_manifest_sha256,
        confirmation_token_expected=confirmation_token_expected,
        confirmation_token_matches=confirmation_token_matches,
        expected_manifest_sha256_matches=expected_manifest_sha256_matches,
        deletion_execution_enabled=deletion_execution_enabled,
        cleanup_attempted=cleanup_attempted,
        warnings=warnings,
        errors=errors,
    )
    if not errors:
        try:
            _write_backup_retention_controlled_apply_outputs(report, artifacts=artifacts)
        except OSError as exc:
            report["status"] = "failed"
            report["errors"] = [*report["errors"], {"message": str(exc)}]
    return report


def _backup_retention_controlled_apply_inputs(args: argparse.Namespace) -> dict[str, Path | None]:
    output_dir = args.operator_resolution_chain_output_dir
    return {
        "apply": args.backup_retention_apply_input
        or (output_dir / BACKUP_RETENTION_APPLY_ARTIFACT_NAMES["apply_json"] if output_dir else None),
        "manifest": args.backup_retention_cleanup_manifest_input
        or (output_dir / BACKUP_RETENTION_APPLY_ARTIFACT_NAMES["manifest_json"] if output_dir else None),
        "blockers": args.backup_retention_apply_blockers_input
        or (output_dir / BACKUP_RETENTION_APPLY_ARTIFACT_NAMES["blockers_json"] if output_dir else None),
    }


def _backup_retention_controlled_apply_artifacts(args: argparse.Namespace) -> dict[str, Path | None]:
    output_dir = args.operator_resolution_chain_output_dir
    overrides = {
        "controlled_apply_json": args.backup_retention_controlled_apply_output,
        "controlled_apply_csv": args.backup_retention_controlled_apply_csv_output,
        "controlled_apply_markdown": args.backup_retention_controlled_apply_markdown_output,
        "blockers_json": args.backup_retention_controlled_apply_blockers_output,
        "blockers_csv": args.backup_retention_controlled_apply_blockers_csv_output,
        "ledger_json": args.backup_retention_deletion_ledger_output,
        "ledger_csv": args.backup_retention_deletion_ledger_csv_output,
        "snapshot_json": args.backup_retention_post_apply_snapshot_output,
        "snapshot_csv": args.backup_retention_post_apply_snapshot_csv_output,
    }
    return {
        key: overrides[key] or (output_dir / file_name if output_dir is not None else None)
        for key, file_name in BACKUP_RETENTION_CONTROLLED_APPLY_ARTIFACT_NAMES.items()
    }


def _backup_retention_controlled_apply_config_errors(args: argparse.Namespace) -> list[dict[str, Any]]:
    errors: list[dict[str, Any]] = []
    if args.backup_retention_max_delete_count < 0:
        errors.append({"message": "invalid_backup_retention_controlled_apply_policy_value:backup_retention_max_delete_count"})
    if args.backup_retention_max_delete_gb < 0:
        errors.append({"message": "invalid_backup_retention_controlled_apply_policy_value:backup_retention_max_delete_gb"})
    if not _backup_retention_backups_dir_is_safe(args.backup_retention_backups_dir):
        errors.append({"message": "backup_retention_backups_dir_unsafe"})
    return errors


def _load_backup_retention_controlled_apply_manifest(
    path: Path | None,
) -> tuple[dict[str, Any], bytes, list[dict[str, Any]]]:
    if path is None or not path.is_file():
        return {}, b"", [{"message": "backup_retention_controlled_apply_input_required"}]
    try:
        content = path.read_bytes()
        payload = json.loads(content.decode("utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError):
        return {}, b"", [{"message": "backup_retention_controlled_apply_input_invalid", "path": str(path)}]
    if (
        not isinstance(payload, dict)
        or payload.get("mode") != "backup-retention-cleanup-manifest-preview"
        or not isinstance(payload.get("cleanup_manifest_rows"), list)
        or not all(isinstance(row, dict) for row in payload.get("cleanup_manifest_rows") or [])
    ):
        return {}, b"", [{"message": "backup_retention_controlled_apply_input_invalid", "path": str(path)}]
    return payload, content, []


def _load_backup_retention_controlled_apply_optional_report(
    path: Path | None,
    *,
    expected_mode: str,
    rows_field: str,
    role: str,
    warnings: list[dict[str, Any]],
) -> dict[str, Any]:
    if path is None or not path.is_file():
        warnings.append({"message": f"backup_retention_controlled_apply_optional_input_missing:{role}"})
        return {}
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        warnings.append({"message": f"backup_retention_controlled_apply_optional_input_unreadable:{role}", "path": str(path)})
        return {}
    if (
        not isinstance(payload, dict)
        or payload.get("mode") != expected_mode
        or not isinstance(payload.get(rows_field), list)
        or not all(isinstance(row, dict) for row in payload.get(rows_field) or [])
    ):
        warnings.append({"message": f"backup_retention_controlled_apply_optional_input_unreadable:{role}", "path": str(path)})
        return {}
    return payload


def _backup_retention_controlled_apply_output_errors(
    args: argparse.Namespace,
    *,
    inputs: dict[str, Path | None],
    artifacts: dict[str, Path | None],
    manifest_rows: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    outputs = [path for path in [*artifacts.values(), args.json_output, args.markdown_output] if path is not None]
    protected = [
        path
        for path in [
            *inputs.values(),
            args.backup_retention_backups_dir,
            *(Path(str(row.get("file_path") or "")) for row in manifest_rows if str(row.get("file_path") or "")),
        ]
        if path is not None
    ]
    for index, output in enumerate(outputs):
        if any(_paths_equal(output, other) for other in outputs[index + 1 :]):
            return [{"message": "backup_retention_controlled_apply_output_must_not_equal_input"}]
        if any(_paths_equal(output, path) for path in protected):
            return [{"message": "backup_retention_controlled_apply_output_must_not_equal_input"}]
        if _path_is_within(output, args.backup_retention_backups_dir):
            return [{"message": "backup_retention_controlled_apply_output_must_not_equal_input"}]
    return []


def _backup_retention_controlled_apply_global_block(
    args: argparse.Namespace,
    *,
    confirmation_token_matches: bool,
    expected_manifest_sha256_matches: bool,
) -> tuple[str, str]:
    if not args.backup_retention_execute:
        return "", ""
    if not args.backup_retention_confirmation_token:
        return "blocked_confirmation_required", "confirmation_token_required"
    if not args.backup_retention_expected_manifest_sha256:
        return "blocked_manifest_hash_required", "expected_manifest_sha256_required"
    if not confirmation_token_matches:
        return "blocked_confirmation_token_mismatch", "confirmation_token_mismatch"
    if not expected_manifest_sha256_matches:
        return "blocked_manifest_hash_mismatch", "expected_manifest_sha256_mismatch"
    return "", ""


def _group_rows_by_field(rows: list[dict[str, Any]], field: str) -> dict[str, list[dict[str, Any]]]:
    grouped: dict[str, list[dict[str, Any]]] = {}
    for row in rows:
        value = str(row.get(field) or "")
        if value:
            grouped.setdefault(value, []).append(row)
    return grouped


def _backup_retention_controlled_apply_current_file(path: Path) -> dict[str, Any]:
    try:
        file_stat = os.lstat(path)
    except OSError:
        return {
            "exists": False,
            "is_regular": False,
            "is_symlink": False,
            "size_bytes": None,
            "mtime_timestamp": None,
            "mtime_utc": "",
        }
    return {
        "exists": True,
        "is_regular": stat.S_ISREG(file_stat.st_mode),
        "is_symlink": stat.S_ISLNK(file_stat.st_mode),
        "size_bytes": file_stat.st_size,
        "mtime_timestamp": file_stat.st_mtime,
        "mtime_utc": _timestamp_to_utc_iso(file_stat.st_mtime),
    }


def _build_backup_retention_controlled_apply_row(
    args: argparse.Namespace,
    manifest_row: dict[str, Any],
    *,
    task139_apply_by_id: dict[str, list[dict[str, Any]]],
    task139_blockers_by_id: dict[str, list[dict[str, Any]]],
    deletion_execution_enabled: bool,
    confirmation_token_matches: bool,
    expected_manifest_sha256_matches: bool,
) -> dict[str, Any]:
    path = Path(str(manifest_row.get("file_path") or ""))
    current = _backup_retention_controlled_apply_current_file(path)
    apply_id = str(manifest_row.get("apply_id") or "")
    task139_rows = task139_apply_by_id.get(apply_id) or []
    task139_metadata_consistent = not task139_apply_by_id or (
        len(task139_rows) == 1
        and str(task139_rows[0].get("file_path") or "") == str(path)
        and _as_int(task139_rows[0].get("current_size_bytes")) == _as_int(manifest_row.get("size_bytes"))
        and str(task139_rows[0].get("current_mtime_utc") or "") == str(manifest_row.get("mtime_utc") or "")
        and task139_rows[0].get("apply_status") == "eligible_manual_delete_preview"
    )
    row = {
        "controlled_apply_id": f"backup_retention_controlled_apply:{manifest_row.get('manifest_id') or hashlib.sha256(str(path).encode('utf-8')).hexdigest()}",
        "manifest_id": str(manifest_row.get("manifest_id") or ""),
        "apply_id": apply_id,
        "file_name": path.name,
        "file_path": str(path),
        "file_extension": _backup_retention_recognized_extension(path.name),
        "task139_size_bytes": _as_int(manifest_row.get("size_bytes")),
        "current_size_bytes": current["size_bytes"],
        "task139_mtime_utc": str(manifest_row.get("mtime_utc") or ""),
        "current_mtime_utc": current["mtime_utc"],
        "current_mtime_timestamp": current["mtime_timestamp"],
        "file_exists_before": current["exists"],
        "file_exists_after": current["exists"],
        "is_regular_file_before": current["is_regular"],
        "is_symlink_before": current["is_symlink"],
        "path_inside_backups_dir": _backup_retention_apply_path_inside_backups_dir(
            path, args.backup_retention_backups_dir
        ),
        "recognized_backup_file": bool(_backup_retention_recognized_extension(path.name)),
        "eligible_for_future_manual_delete": manifest_row.get("eligible_for_future_manual_delete") is True,
        "manual_review_required": manifest_row.get("manual_review_required") is True,
        "manual_review_status": (
            "required_confirmed_by_token_and_manifest_hash"
            if args.backup_retention_require_manual_review and deletion_execution_enabled
            else "required_pending_explicit_execute_confirmation"
            if args.backup_retention_require_manual_review
            else "not_required_by_configuration"
        ),
        "execute_requested": args.backup_retention_execute,
        "deletion_execution_enabled": deletion_execution_enabled,
        "confirmation_token_matches": confirmation_token_matches,
        "expected_manifest_sha256_matches": expected_manifest_sha256_matches,
        "controlled_apply_status": "",
        "controlled_apply_severity": "",
        "controlled_apply_action": "",
        "controlled_apply_reason_codes": [],
        "controlled_apply_errors": [],
        "controlled_apply_warnings": [],
        "delete_order": None,
        "delete_limit_status": "within_limit",
        "reclaim_limit_status": "within_limit",
        "would_delete_file": False,
        "did_delete_file": False,
        "delete_exception": "",
        "ledger_status": "",
        "ledger_reason_codes": [],
    }
    status, reason = _classify_backup_retention_controlled_apply_row(
        args,
        row,
        manifest_row=manifest_row,
        task139_metadata_consistent=task139_metadata_consistent,
        task139_blocker_present=bool(task139_blockers_by_id.get(apply_id)),
    )
    if status:
        _set_backup_retention_controlled_apply_status(row, status=status, reason=reason)
    return row


def _classify_backup_retention_controlled_apply_row(
    args: argparse.Namespace,
    row: dict[str, Any],
    *,
    manifest_row: dict[str, Any],
    task139_metadata_consistent: bool,
    task139_blocker_present: bool,
) -> tuple[str, str]:
    if (
        manifest_row.get("eligible_for_future_manual_delete") is not True
        or manifest_row.get("cleanup_script_line_enabled") is not False
        or manifest_row.get("would_delete_file") is not False
        or task139_blocker_present
        or not task139_metadata_consistent
    ):
        return "blocked_not_manifest_eligible", "task139_manifest_not_eligible_or_inconsistent"
    if args.backup_retention_require_manual_review and manifest_row.get("manual_review_required") is not True:
        return "blocked_manual_review_required", "manual_review_metadata_required"
    return _revalidate_backup_retention_controlled_apply_row(
        row,
        backups_dir=args.backup_retention_backups_dir,
    )


def _revalidate_backup_retention_controlled_apply_row(
    row: dict[str, Any],
    *,
    backups_dir: Path,
) -> tuple[str, str]:
    path = Path(row["file_path"])
    current = _backup_retention_controlled_apply_current_file(path)
    row["file_exists_after"] = current["exists"]
    row["current_size_bytes"] = current["size_bytes"]
    row["current_mtime_utc"] = current["mtime_utc"]
    row["current_mtime_timestamp"] = current["mtime_timestamp"]
    if not _backup_retention_apply_path_inside_backups_dir(path, backups_dir):
        return "blocked_unsafe_path", "unsafe_path"
    if current["is_symlink"]:
        return "blocked_symlink", "symlink_not_allowed"
    if not current["exists"]:
        return "blocked_file_missing", "file_missing"
    if not current["is_regular"]:
        return "blocked_not_regular_file", "file_not_regular"
    if not _backup_retention_recognized_extension(path.name):
        return "blocked_unrecognized_extension", "unrecognized_extension"
    if row["task139_size_bytes"] != current["size_bytes"]:
        return "blocked_file_drift_detected", "file_size_drift"
    task139_mtime = _parse_utc_timestamp(row["task139_mtime_utc"])
    if (
        task139_mtime is None
        or current["mtime_timestamp"] is None
        or abs(float(current["mtime_timestamp"]) - task139_mtime) > 1.0
    ):
        return "blocked_file_drift_detected", "file_mtime_drift"
    return "", ""


def _apply_backup_retention_controlled_apply_limits(
    args: argparse.Namespace,
    *,
    rows: list[dict[str, Any]],
) -> None:
    candidates = sorted(
        (row for row in rows if not row["controlled_apply_status"]),
        key=lambda row: (row["current_mtime_timestamp"] or 0, row["file_path"]),
    )
    accepted_count = 0
    accepted_bytes = 0
    max_bytes = args.backup_retention_max_delete_gb * (1024**3)
    for delete_order, row in enumerate(candidates, start=1):
        row["delete_order"] = delete_order
        size_bytes = int(row["current_size_bytes"] or 0)
        if accepted_count >= args.backup_retention_max_delete_count:
            row["delete_limit_status"] = "delete_count_limit_exceeded"
            _set_backup_retention_controlled_apply_status(
                row,
                status="blocked_delete_count_limit_exceeded",
                reason="delete_count_limit_exceeded",
            )
            continue
        if accepted_bytes + size_bytes > max_bytes:
            row["reclaim_limit_status"] = "reclaim_size_limit_exceeded"
            _set_backup_retention_controlled_apply_status(
                row,
                status="blocked_reclaim_limit_exceeded",
                reason="reclaim_size_limit_exceeded",
            )
            continue
        accepted_count += 1
        accepted_bytes += size_bytes


def _set_backup_retention_controlled_apply_status(
    row: dict[str, Any],
    *,
    status: str,
    reason: str,
) -> None:
    row["controlled_apply_status"] = status
    row["controlled_apply_reason_codes"] = [reason] if reason else []
    row["controlled_apply_severity"] = "info" if status in {"dry_run_eligible_for_delete", "deleted"} else "error" if status.startswith("failed_") else "warning"
    row["controlled_apply_action"] = (
        "delete_backup_file_after_all_guards"
        if status == "deleted"
        else "preview_delete_after_all_guards"
        if status == "dry_run_eligible_for_delete"
        else "block"
    )
    row["would_delete_file"] = status == "dry_run_eligible_for_delete"
    row["ledger_status"] = (
        "deleted"
        if status == "deleted"
        else "dry_run_noop"
        if status == "dry_run_eligible_for_delete"
        else "failed"
        if status.startswith("failed_")
        else "blocked"
    )
    row["ledger_reason_codes"] = [reason] if reason else []


def _backup_retention_controlled_apply_manifest_unchanged(path: Path | None, expected: bytes) -> bool:
    try:
        return path is not None and path.is_file() and path.read_bytes() == expected
    except OSError:
        return False


def _delete_backup_file_after_all_guards(
    args: argparse.Namespace,
    row: dict[str, Any],
    *,
    confirmation_token_matches: bool,
    expected_manifest_sha256_matches: bool,
) -> None:
    path = Path(row["file_path"])
    if args.mode != "backup-retention-controlled-apply" or not args.backup_retention_execute:
        raise RuntimeError("guarded backup deletion called outside controlled execute mode")
    if not confirmation_token_matches or not expected_manifest_sha256_matches:
        raise RuntimeError("guarded backup deletion confirmation mismatch")
    status, reason = _revalidate_backup_retention_controlled_apply_row(
        row,
        backups_dir=args.backup_retention_backups_dir,
    )
    if status:
        raise RuntimeError(reason)
    path.unlink()


def _build_backup_retention_deletion_ledger_rows(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return [
        {
            "ledger_id": f"backup_retention_deletion_ledger:{row['controlled_apply_id']}",
            "controlled_apply_id": row["controlled_apply_id"],
            "file_name": row["file_name"],
            "file_path": row["file_path"],
            "size_bytes": row["task139_size_bytes"],
            "mtime_utc": row["task139_mtime_utc"],
            "execute_requested": row["execute_requested"],
            "deletion_execution_enabled": row["deletion_execution_enabled"],
            "controlled_apply_status": row["controlled_apply_status"],
            "did_delete_file": row["did_delete_file"],
            "file_exists_before": row["file_exists_before"],
            "file_exists_after": row["file_exists_after"],
            "delete_exception": row["delete_exception"],
            "ledger_status": row["ledger_status"] or "pending_controlled_delete",
            "ledger_reason_codes": row["ledger_reason_codes"],
        }
        for row in rows
    ]


def _persist_backup_retention_controlled_apply_ledger(
    rows: list[dict[str, Any]],
    *,
    json_path: Path | None,
    csv_path: Path | None,
    safety_flags: dict[str, Any],
) -> None:
    if json_path is not None:
        _write_json_report_atomic(
            {
                "status": "warning",
                "mode": "backup-retention-deletion-ledger",
                "ledger_row_count": len(rows),
                "deletion_ledger_rows": rows,
                **safety_flags,
            },
            json_path,
        )
    if csv_path is not None:
        _write_flat_csv_atomic(rows, BACKUP_RETENTION_DELETION_LEDGER_FIELDS, csv_path)


def _write_json_report_atomic(payload: dict[str, Any], path: Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile("w", encoding="utf-8", dir=path.parent, delete=False) as handle:
        handle.write(json.dumps(payload, ensure_ascii=False, indent=2) + "\n")
        temp_path = Path(handle.name)
    os.replace(temp_path, path)


def _write_flat_csv_atomic(rows: list[dict[str, Any]], fieldnames: list[str], path: Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile("w", encoding="utf-8", newline="", dir=path.parent, delete=False) as handle:
        writer = csv.DictWriter(handle, fieldnames=fieldnames, extrasaction="ignore")
        writer.writeheader()
        for row in rows:
            writer.writerow({field: _csv_value(row.get(field)) for field in fieldnames})
        temp_path = Path(handle.name)
    os.replace(temp_path, path)


def _scan_backup_retention_controlled_apply_snapshot(
    backups_dir: Path,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    inventory_rows, warnings, errors = _scan_backup_retention_inventory(backups_dir)
    warnings.extend(errors)
    rows = [
        {
            "snapshot_id": f"backup_retention_post_apply_snapshot:{hashlib.sha256(str(row['path']).encode('utf-8')).hexdigest()}",
            "file_name": row["file_name"],
            "file_path": row["path"],
            "entry_type": row["entry_type"],
            "recognized_backup_file": row["recognized_backup"],
            "size_bytes": row["size_bytes"],
            "size_mb": row["size_mb"],
            "size_gb": row["size_gb"],
            "mtime_utc": row["mtime_utc"],
            "is_regular_file": row["is_regular_file"],
            "is_symlink": row["is_symlink"],
        }
        for row in inventory_rows
    ]
    return rows, _dedupe_messages(warnings)


def _build_backup_retention_controlled_apply_blocker_rows(
    rows: list[dict[str, Any]],
    *,
    task139_blocker_rows: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    blockers = [
        {
            "blocker_id": f"backup_retention_controlled_apply_blocker:{row['controlled_apply_id']}:{reason}",
            "controlled_apply_id": row["controlled_apply_id"],
            "manifest_id": row["manifest_id"],
            "apply_id": row["apply_id"],
            "file_name": row["file_name"],
            "file_path": row["file_path"],
            "controlled_apply_status": row["controlled_apply_status"],
            "blocker_code": reason,
            "severity": row["controlled_apply_severity"],
            "next_manual_action": "Resolve this blocker and regenerate Task139 artifacts before any future controlled execute.",
            "would_delete_file": False,
        }
        for row in rows
        if row["controlled_apply_status"] not in {"dry_run_eligible_for_delete", "deleted"}
        for reason in (row["controlled_apply_reason_codes"] or ["unknown_readiness"])
    ]
    blockers.extend(
        {
            "blocker_id": f"backup_retention_controlled_apply_blocker:task139:{row.get('blocker_id') or index}",
            "controlled_apply_id": "",
            "manifest_id": "",
            "apply_id": str(row.get("apply_id") or ""),
            "file_name": str(row.get("file_name") or ""),
            "file_path": str(row.get("file_path") or ""),
            "controlled_apply_status": "task139_blocker_diagnostic",
            "blocker_code": str(row.get("blocker_code") or "task139_blocker_present"),
            "severity": str(row.get("severity") or "warning"),
            "next_manual_action": "Review the Task139 blocker before any future controlled execute.",
            "would_delete_file": False,
        }
        for index, row in enumerate(task139_blocker_rows)
    )
    return blockers


def _backup_retention_controlled_apply_estimated_bytes(rows: list[dict[str, Any]]) -> int:
    return sum(
        int(row["task139_size_bytes"] or 0)
        for row in rows
        if row["controlled_apply_status"] in {"", "dry_run_eligible_for_delete", "deleted"}
    )


def _backup_retention_controlled_apply_safety_flags(
    *,
    execute_requested: bool,
    cleanup_attempted: bool,
    deleted_count: int,
    estimated_reclaimable_bytes: int,
) -> dict[str, Any]:
    flags = _backup_retention_safety_flags()
    flags.update(
        {
            "read_only": False,
            "dry_run_only": not execute_requested,
            "cleanup_executed": cleanup_attempted,
            "files_deleted": deleted_count > 0,
            "would_delete_files": estimated_reclaimable_bytes > 0 and not execute_requested,
        }
    )
    return flags


def _build_backup_retention_controlled_apply_report(
    args: argparse.Namespace,
    *,
    controlled_apply_rows: list[dict[str, Any]],
    blocker_rows: list[dict[str, Any]],
    ledger_rows: list[dict[str, Any]],
    snapshot_rows: list[dict[str, Any]],
    artifacts: dict[str, Path | None],
    manifest_rows: list[dict[str, Any]],
    cleanup_manifest_sha256: str,
    confirmation_token_expected: str,
    confirmation_token_matches: bool,
    expected_manifest_sha256_matches: bool,
    deletion_execution_enabled: bool,
    cleanup_attempted: bool,
    warnings: list[dict[str, Any]],
    errors: list[dict[str, Any]],
) -> dict[str, Any]:
    warnings = _dedupe_messages(warnings)
    deleted_count = sum(bool(row["did_delete_file"]) for row in controlled_apply_rows)
    dry_run_eligible_count = sum(row["controlled_apply_status"] == "dry_run_eligible_for_delete" for row in controlled_apply_rows)
    failed_count = sum(row["controlled_apply_status"].startswith("failed_") for row in controlled_apply_rows)
    blocked_count = sum(row["controlled_apply_status"].startswith("blocked_") for row in controlled_apply_rows)
    manifest_reclaimable_bytes = sum(int(row.get("size_bytes") or 0) for row in manifest_rows)
    estimated_reclaimable_bytes = _backup_retention_controlled_apply_estimated_bytes(controlled_apply_rows)
    actual_reclaimed_bytes = sum(int(row["task139_size_bytes"] or 0) for row in controlled_apply_rows if row["did_delete_file"])
    recognized_snapshot_rows = [row for row in snapshot_rows if row["recognized_backup_file"]]
    global_execute_blocked = bool(args.backup_retention_execute and not deletion_execution_enabled and not errors)
    status = (
        "failed"
        if errors
        else "blocked"
        if global_execute_blocked
        else "warning"
        if warnings or blocker_rows or dry_run_eligible_count or failed_count
        else "passed"
    )
    safety_flags = _backup_retention_controlled_apply_safety_flags(
        execute_requested=args.backup_retention_execute,
        cleanup_attempted=cleanup_attempted,
        deleted_count=deleted_count,
        estimated_reclaimable_bytes=estimated_reclaimable_bytes,
    )
    return {
        "status": status,
        "mode": "backup-retention-controlled-apply",
        "backups_dir": str(args.backup_retention_backups_dir),
        "execute_requested": args.backup_retention_execute,
        "deletion_execution_enabled": deletion_execution_enabled,
        "cleanup_manifest_sha256": cleanup_manifest_sha256,
        "confirmation_token_expected": confirmation_token_expected,
        "confirmation_token_provided": args.backup_retention_confirmation_token,
        "confirmation_token_matches": confirmation_token_matches,
        "expected_manifest_sha256_provided": args.backup_retention_expected_manifest_sha256,
        "expected_manifest_sha256_matches": expected_manifest_sha256_matches,
        "manifest_input_count": len(manifest_rows),
        "controlled_apply_row_count": len(controlled_apply_rows),
        "dry_run_eligible_count": dry_run_eligible_count,
        "deleted_count": deleted_count,
        "blocked_count": blocked_count,
        "failed_count": failed_count,
        "ledger_row_count": len(ledger_rows),
        "post_apply_backup_file_count": len(snapshot_rows),
        "post_apply_recognized_backup_file_count": len(recognized_snapshot_rows),
        "post_apply_recognized_backup_size_bytes": sum(int(row["size_bytes"] or 0) for row in recognized_snapshot_rows),
        "post_apply_recognized_backup_size_gb": _bytes_to_gb(sum(int(row["size_bytes"] or 0) for row in recognized_snapshot_rows)),
        "manifest_reclaimable_bytes": manifest_reclaimable_bytes,
        "manifest_reclaimable_gb": _bytes_to_gb(manifest_reclaimable_bytes),
        "estimated_reclaimable_bytes": estimated_reclaimable_bytes,
        "estimated_reclaimable_gb": _bytes_to_gb(estimated_reclaimable_bytes),
        "actual_reclaimed_bytes": actual_reclaimed_bytes,
        "actual_reclaimed_gb": _bytes_to_gb(actual_reclaimed_bytes),
        "max_delete_count": args.backup_retention_max_delete_count,
        "max_delete_gb": args.backup_retention_max_delete_gb,
        "require_manual_review": args.backup_retention_require_manual_review,
        "controlled_apply_status_counts": _count_values(controlled_apply_rows, "controlled_apply_status"),
        "blocker_code_counts": _count_values(blocker_rows, "blocker_code"),
        "controlled_apply_rows": controlled_apply_rows,
        "blocker_rows": blocker_rows,
        "deletion_ledger_rows": ledger_rows,
        "post_apply_snapshot_rows": snapshot_rows,
        "artifacts": {key: _path_value(path) for key, path in artifacts.items()},
        "warnings": warnings,
        "errors": errors,
        "next_steps": _next_steps("backup-retention-controlled-apply", status),
        **safety_flags,
    }


def _write_backup_retention_controlled_apply_outputs(
    report: dict[str, Any],
    *,
    artifacts: dict[str, Path | None],
) -> None:
    if artifacts["controlled_apply_json"] is not None:
        write_json_report(report, artifacts["controlled_apply_json"])
    if artifacts["controlled_apply_csv"] is not None:
        _write_flat_csv(report["controlled_apply_rows"], BACKUP_RETENTION_CONTROLLED_APPLY_FIELDS, artifacts["controlled_apply_csv"])
    if artifacts["controlled_apply_markdown"] is not None:
        write_backup_retention_controlled_apply_markdown(report, artifacts["controlled_apply_markdown"])
    if artifacts["blockers_json"] is not None:
        write_json_report(_backup_retention_controlled_apply_blockers_report(report), artifacts["blockers_json"])
    if artifacts["blockers_csv"] is not None:
        _write_flat_csv(report["blocker_rows"], BACKUP_RETENTION_CONTROLLED_APPLY_BLOCKER_FIELDS, artifacts["blockers_csv"])
    _persist_backup_retention_controlled_apply_ledger(
        report["deletion_ledger_rows"],
        json_path=artifacts["ledger_json"],
        csv_path=artifacts["ledger_csv"],
        safety_flags=_backup_retention_controlled_apply_safety_flags(
            execute_requested=report["execute_requested"],
            cleanup_attempted=report["cleanup_executed"],
            deleted_count=report["deleted_count"],
            estimated_reclaimable_bytes=report["estimated_reclaimable_bytes"],
        ),
    )
    if artifacts["snapshot_json"] is not None:
        write_json_report(_backup_retention_controlled_apply_snapshot_report(report), artifacts["snapshot_json"])
    if artifacts["snapshot_csv"] is not None:
        _write_flat_csv(report["post_apply_snapshot_rows"], BACKUP_RETENTION_POST_APPLY_SNAPSHOT_FIELDS, artifacts["snapshot_csv"])


def _backup_retention_controlled_apply_blockers_report(report: dict[str, Any]) -> dict[str, Any]:
    return {
        "status": report["status"],
        "mode": "backup-retention-controlled-apply-blockers",
        "blocker_row_count": len(report["blocker_rows"]),
        "blocker_code_counts": report["blocker_code_counts"],
        "blocker_rows": report["blocker_rows"],
        **_backup_retention_controlled_apply_safety_flags(
            execute_requested=report["execute_requested"],
            cleanup_attempted=report["cleanup_executed"],
            deleted_count=report["deleted_count"],
            estimated_reclaimable_bytes=report["estimated_reclaimable_bytes"],
        ),
    }


def _backup_retention_controlled_apply_snapshot_report(report: dict[str, Any]) -> dict[str, Any]:
    return {
        "status": report["status"],
        "mode": "backup-retention-post-apply-snapshot",
        "post_apply_backup_file_count": report["post_apply_backup_file_count"],
        "post_apply_recognized_backup_file_count": report["post_apply_recognized_backup_file_count"],
        "post_apply_recognized_backup_size_bytes": report["post_apply_recognized_backup_size_bytes"],
        "post_apply_recognized_backup_size_gb": report["post_apply_recognized_backup_size_gb"],
        "post_apply_snapshot_rows": report["post_apply_snapshot_rows"],
        **_backup_retention_controlled_apply_safety_flags(
            execute_requested=report["execute_requested"],
            cleanup_attempted=report["cleanup_executed"],
            deleted_count=report["deleted_count"],
            estimated_reclaimable_bytes=report["estimated_reclaimable_bytes"],
        ),
    }


def run_backup_retention_execute_readiness_board(args: argparse.Namespace) -> dict[str, Any]:
    warnings: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    inputs = _backup_retention_execute_readiness_inputs(args)
    task140_report, task140_errors = _load_backup_retention_execute_readiness_required_report(
        inputs["task140"],
        expected_mode="backup-retention-controlled-apply",
        missing_code="backup_retention_execute_readiness_task140_input_required",
        invalid_code="backup_retention_execute_readiness_task140_input_invalid",
    )
    manifest_report, manifest_errors, manifest_bytes = _load_backup_retention_execute_readiness_manifest(
        inputs["manifest"]
    )
    errors.extend(task140_errors)
    errors.extend(manifest_errors)
    task138_report = _load_backup_retention_execute_readiness_optional_report(
        inputs["preview"],
        expected_mode="backup-retention-preview",
        role="task138_preview",
        warnings=warnings,
    )
    _load_backup_retention_execute_readiness_optional_report(
        inputs["apply_preview"],
        expected_mode="backup-retention-apply-draft-preview",
        role="task139_apply_preview",
        warnings=warnings,
    )
    ledger_report = _load_backup_retention_execute_readiness_optional_report(
        inputs["ledger"],
        expected_mode="backup-retention-deletion-ledger",
        role="task140_deletion_ledger",
        warnings=warnings,
    )
    snapshot_report = _load_backup_retention_execute_readiness_optional_report(
        inputs["snapshot"],
        expected_mode="backup-retention-post-apply-snapshot",
        role="task140_post_apply_snapshot",
        warnings=warnings,
    )
    manifest_rows = [
        row
        for row in manifest_report.get("cleanup_manifest_rows") or []
        if isinstance(row, dict)
    ]
    artifacts = _backup_retention_execute_readiness_artifacts(args)
    errors.extend(
        _backup_retention_execute_readiness_output_errors(
            args,
            inputs=inputs,
            artifacts=artifacts,
            manifest_rows=manifest_rows,
        )
    )
    manifest_sha256 = hashlib.sha256(manifest_bytes).hexdigest() if manifest_bytes else ""
    board_rows: list[dict[str, Any]] = []
    if not errors:
        board_rows = _build_backup_retention_execute_readiness_board_rows(
            args,
            task140_report=task140_report,
            manifest_report=manifest_report,
            manifest_sha256=manifest_sha256,
            task138_report=task138_report,
            ledger_report=ledger_report,
            snapshot_report=snapshot_report,
            warnings=warnings,
        )
    blocker_rows = _backup_retention_execute_readiness_blocker_rows(board_rows)
    readiness_status = _backup_retention_execute_readiness_status(errors=errors, board_rows=board_rows)
    report = _build_backup_retention_execute_readiness_report(
        args,
        task140_report=task140_report,
        manifest_report=manifest_report,
        task138_report=task138_report,
        ledger_report=ledger_report,
        snapshot_report=snapshot_report,
        manifest_sha256=manifest_sha256,
        readiness_status=readiness_status,
        board_rows=board_rows,
        blocker_rows=blocker_rows,
        artifacts=artifacts,
        warnings=warnings,
        errors=errors,
    )
    if not errors:
        try:
            _write_backup_retention_execute_readiness_outputs(report, artifacts=artifacts)
        except OSError as exc:
            report["status"] = "failed"
            report["errors"] = [*report["errors"], {"message": str(exc)}]
    return report


def _backup_retention_execute_readiness_inputs(args: argparse.Namespace) -> dict[str, Path | None]:
    output_dir = args.operator_resolution_chain_output_dir
    return {
        "preview": args.backup_retention_preview_input
        or (output_dir / BACKUP_RETENTION_ARTIFACT_NAMES["preview_json"] if output_dir else None),
        "apply_preview": args.backup_retention_apply_preview_input
        or (output_dir / BACKUP_RETENTION_APPLY_ARTIFACT_NAMES["apply_json"] if output_dir else None),
        "manifest": args.backup_retention_cleanup_manifest_input
        or (output_dir / BACKUP_RETENTION_APPLY_ARTIFACT_NAMES["manifest_json"] if output_dir else None),
        "task140": args.backup_retention_controlled_apply_input
        or (
            output_dir / BACKUP_RETENTION_CONTROLLED_APPLY_ARTIFACT_NAMES["controlled_apply_json"]
            if output_dir
            else None
        ),
        "ledger": args.backup_retention_deletion_ledger_input
        or (output_dir / BACKUP_RETENTION_CONTROLLED_APPLY_ARTIFACT_NAMES["ledger_json"] if output_dir else None),
        "snapshot": args.backup_retention_post_apply_snapshot_input
        or (output_dir / BACKUP_RETENTION_CONTROLLED_APPLY_ARTIFACT_NAMES["snapshot_json"] if output_dir else None),
    }


def _backup_retention_execute_readiness_artifacts(args: argparse.Namespace) -> dict[str, Path | None]:
    output_dir = args.operator_resolution_chain_output_dir
    overrides = {
        "readiness_json": args.backup_retention_execute_readiness_output,
        "readiness_csv": args.backup_retention_execute_readiness_csv_output,
        "readiness_markdown": args.backup_retention_execute_readiness_markdown_output,
        "board_json": args.backup_retention_execute_readiness_board_output,
        "board_csv": args.backup_retention_execute_readiness_board_csv_output,
        "blockers_json": args.backup_retention_execute_readiness_blockers_output,
        "blockers_csv": args.backup_retention_execute_readiness_blockers_csv_output,
    }
    return {
        key: overrides[key] or (output_dir / file_name if output_dir is not None else None)
        for key, file_name in BACKUP_RETENTION_EXECUTE_READINESS_ARTIFACT_NAMES.items()
    }


def _load_backup_retention_execute_readiness_required_report(
    path: Path | None,
    *,
    expected_mode: str,
    missing_code: str,
    invalid_code: str,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    if path is None or not path.is_file():
        return {}, [{"message": missing_code}]
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}, [{"message": invalid_code, "path": str(path)}]
    if not isinstance(payload, dict) or payload.get("mode") != expected_mode:
        return {}, [{"message": invalid_code, "path": str(path)}]
    return payload, []


def _load_backup_retention_execute_readiness_manifest(
    path: Path | None,
) -> tuple[dict[str, Any], list[dict[str, Any]], bytes]:
    if path is None or not path.is_file():
        return {}, [{"message": "backup_retention_execute_readiness_manifest_input_required"}], b""
    try:
        content = path.read_bytes()
        payload = json.loads(content.decode("utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError):
        return {}, [{"message": "backup_retention_execute_readiness_manifest_input_invalid", "path": str(path)}], b""
    if (
        not isinstance(payload, dict)
        or payload.get("mode") != "backup-retention-cleanup-manifest-preview"
        or not isinstance(payload.get("cleanup_manifest_rows"), list)
        or not all(isinstance(row, dict) for row in payload.get("cleanup_manifest_rows") or [])
    ):
        return {}, [{"message": "backup_retention_execute_readiness_manifest_input_invalid", "path": str(path)}], b""
    return payload, [], content


def _load_backup_retention_execute_readiness_optional_report(
    path: Path | None,
    *,
    expected_mode: str,
    role: str,
    warnings: list[dict[str, Any]],
) -> dict[str, Any]:
    if path is None or not path.is_file():
        warnings.append({"message": f"backup_retention_execute_readiness_optional_input_missing:{role}"})
        return {}
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        warnings.append({"message": f"backup_retention_execute_readiness_optional_input_unreadable:{role}", "path": str(path)})
        return {}
    if not isinstance(payload, dict) or payload.get("mode") != expected_mode:
        warnings.append({"message": f"backup_retention_execute_readiness_optional_input_unreadable:{role}", "path": str(path)})
        return {}
    return payload


def _backup_retention_execute_readiness_output_errors(
    args: argparse.Namespace,
    *,
    inputs: dict[str, Path | None],
    artifacts: dict[str, Path | None],
    manifest_rows: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    outputs = [path for path in [*artifacts.values(), args.json_output, args.markdown_output] if path is not None]
    protected = [
        path
        for path in [
            *inputs.values(),
            args.backup_retention_backups_dir,
            *(Path(str(row.get("file_path") or "")) for row in manifest_rows if str(row.get("file_path") or "")),
        ]
        if path is not None
    ]
    for index, output in enumerate(outputs):
        if any(_paths_equal(output, other) for other in outputs[index + 1 :]):
            return [{"message": "backup_retention_execute_readiness_output_must_not_equal_input"}]
        if any(_paths_equal(output, path) for path in protected):
            return [{"message": "backup_retention_execute_readiness_output_must_not_equal_input"}]
        if _path_is_within(output, args.backup_retention_backups_dir):
            return [{"message": "backup_retention_execute_readiness_output_must_not_equal_input"}]
    return []


def _backup_retention_execute_readiness_check(
    rows: list[dict[str, Any]],
    *,
    group: str,
    name: str,
    status: str,
    reasons: list[str],
    observed: Any,
    expected: Any,
    action: str,
    hint: str,
) -> None:
    rows.append(
        {
            "board_check_id": f"backup_retention_execute_readiness:{group}:{name}".replace(" ", "_"),
            "check_group": group,
            "check_name": name,
            "check_status": status,
            "check_severity": "info" if status == "passed" else "warning" if status == "warning" else "error",
            "check_reason_codes": reasons,
            "check_observed_value": observed,
            "check_expected_value": expected,
            "operator_action": action,
            "safe_hint": hint,
        }
    )


def _build_backup_retention_execute_readiness_board_rows(
    args: argparse.Namespace,
    *,
    task140_report: dict[str, Any],
    manifest_report: dict[str, Any],
    manifest_sha256: str,
    task138_report: dict[str, Any],
    ledger_report: dict[str, Any],
    snapshot_report: dict[str, Any],
    warnings: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    expected_limit_blocker_count, unsafe_blocker_count = _backup_retention_execute_readiness_blocker_counts(task140_report)
    ledger_rows = _backup_retention_execute_readiness_ledger_rows(task140_report, ledger_report)
    dry_run_eligible_count = int(task140_report.get("dry_run_eligible_count") or 0)
    estimated_gb = float(task140_report.get("estimated_reclaimable_gb") or 0.0)
    pressure_known, pressure_present = _backup_retention_execute_readiness_backup_pressure(task138_report)
    paper_value = _first_present(task140_report, ("paper_schedule_status", "paper_schedule_state", "paper_schedule"))
    financial_count = _first_present(task140_report, ("financial_reports_count", "financial_reports_count_after"))
    if paper_value is None or financial_count is None:
        warnings.append({"message": "backup_retention_execute_readiness_db_paper_safety_unknown_from_artifacts"})
    _backup_retention_execute_readiness_check(
        rows,
        group="artifact_presence",
        name="Task140 controlled apply dry-run present",
        status="passed",
        reasons=[],
        observed=task140_report.get("mode"),
        expected="backup-retention-controlled-apply",
        action="Review Task140 dry-run artifact.",
        hint="Task141 uses this artifact as the readiness source of truth.",
    )
    _backup_retention_execute_readiness_check(
        rows,
        group="artifact_presence",
        name="Task139 cleanup manifest present",
        status="passed",
        reasons=[],
        observed=manifest_report.get("manifest_row_count", len(manifest_report.get("cleanup_manifest_rows") or [])),
        expected="readable cleanup manifest",
        action="Review the candidate manifest.",
        hint="Task141 does not modify manifest files.",
    )
    task140_dry_run = (
        task140_report.get("execute_requested") is False
        and task140_report.get("deletion_execution_enabled") is False
        and task140_report.get("dry_run_only") is True
    )
    _backup_retention_execute_readiness_check(
        rows,
        group="task140_dry_run_safety",
        name="Task140 was dry-run only",
        status="passed" if task140_dry_run else "failed",
        reasons=[] if task140_dry_run else ["task140_not_dry_run"],
        observed=f"execute_requested={task140_report.get('execute_requested')}; deletion_execution_enabled={task140_report.get('deletion_execution_enabled')}; dry_run_only={task140_report.get('dry_run_only')}",
        expected="execute_requested=false; deletion_execution_enabled=false; dry_run_only=true",
        action="Rerun Task140 dry-run before considering execute.",
        hint="Task141 must never evaluate an already-executed Task140 artifact as ready.",
    )
    files_deleted = _backup_retention_execute_readiness_deleted_evidence(task140_report, ledger_rows)
    _backup_retention_execute_readiness_check(
        rows,
        group="task140_dry_run_safety",
        name="No files were deleted",
        status="passed" if not files_deleted else "failed",
        reasons=[] if not files_deleted else ["files_already_deleted"],
        observed=f"deleted_count={task140_report.get('deleted_count')}; files_deleted={task140_report.get('files_deleted')}; actual_reclaimed_bytes={task140_report.get('actual_reclaimed_bytes')}",
        expected="no deletion evidence",
        action="Stop and inspect Task140 execution artifacts.",
        hint="Readiness requires proof that Task140 remained a dry-run.",
    )
    task140_status_allowed = _backup_retention_apply_preview_status_allowed(
        args.backup_retention_require_dry_run_status,
        str(task140_report.get("status") or ""),
    )
    _backup_retention_execute_readiness_check(
        rows,
        group="task140_dry_run_safety",
        name="Task140 status allowed",
        status="passed" if task140_status_allowed else "failed",
        reasons=[] if task140_status_allowed else ["task140_status_not_allowed"],
        observed=task140_report.get("status"),
        expected=args.backup_retention_require_dry_run_status,
        action="Review Task140 warnings before execute.",
        hint="The default accepts warning because bounded dry-run candidates create a warning status.",
    )
    hash_matches = bool(manifest_sha256 and manifest_sha256 == task140_report.get("cleanup_manifest_sha256"))
    _backup_retention_execute_readiness_check(
        rows,
        group="manifest_integrity",
        name="Manifest SHA-256 available and stable",
        status="passed" if hash_matches else "failed",
        reasons=[] if hash_matches else ["manifest_hash_missing_or_mismatch"],
        observed=task140_report.get("cleanup_manifest_sha256"),
        expected=manifest_sha256,
        action="Regenerate Task139 and Task140 dry-run artifacts.",
        hint="The future execute command must use the exact manifest SHA-256.",
    )
    token_available = bool(task140_report.get("confirmation_token_expected"))
    _backup_retention_execute_readiness_check(
        rows,
        group="manifest_integrity",
        name="Confirmation token available",
        status="passed" if token_available else "failed",
        reasons=[] if token_available else ["confirmation_token_missing"],
        observed=task140_report.get("confirmation_token_expected"),
        expected="non-empty deterministic token",
        action="Rerun Task140 dry-run to regenerate token.",
        hint="Task141 only displays the token; it never executes cleanup.",
    )
    _backup_retention_execute_readiness_check(
        rows,
        group="candidate_quality",
        name="Dry-run eligible rows present",
        status="passed" if dry_run_eligible_count > 0 else "failed",
        reasons=[] if dry_run_eligible_count > 0 else ["no_dry_run_eligible_rows"],
        observed=dry_run_eligible_count,
        expected="> 0",
        action="Review Task139 manifest and Task140 dry-run blockers.",
        hint="No execute review is useful without a bounded eligible batch.",
    )
    limit_match = (
        int(task140_report.get("max_delete_count") or -1) == args.backup_retention_proposed_max_delete_count
        and abs(float(task140_report.get("max_delete_gb") or -1.0) - args.backup_retention_proposed_max_delete_gb) < 0.000001
        and dry_run_eligible_count <= args.backup_retention_proposed_max_delete_count
        and estimated_gb <= args.backup_retention_proposed_max_delete_gb + 0.000001
    )
    _backup_retention_execute_readiness_check(
        rows,
        group="delete_limits",
        name="Dry-run bounded by proposed limits",
        status="passed" if limit_match else "failed",
        reasons=[] if limit_match else ["delete_limits_mismatch"],
        observed=f"task140_count={task140_report.get('max_delete_count')}; task140_gb={task140_report.get('max_delete_gb')}; eligible={dry_run_eligible_count}; estimated_gb={estimated_gb}",
        expected=f"count={args.backup_retention_proposed_max_delete_count}; gb={args.backup_retention_proposed_max_delete_gb}",
        action="Rerun Task140 dry-run with the same proposed limits.",
        hint="Readiness requires the command template to match the dry-run batch.",
    )
    _backup_retention_execute_readiness_check(
        rows,
        group="candidate_quality",
        name="No unsafe blockers present",
        status="passed" if unsafe_blocker_count == 0 else "failed",
        reasons=[] if unsafe_blocker_count == 0 else ["unsafe_blockers_present"],
        observed=f"unsafe={unsafe_blocker_count}; expected_limit={expected_limit_blocker_count}",
        expected="unsafe=0",
        action="Resolve unsafe blockers and regenerate Task139/Task140 artifacts.",
        hint="Expected limit blockers may remain advisory; unsafe filesystem blockers cannot.",
    )
    ledger_safe = bool(ledger_rows) and all(row.get("did_delete_file") is False for row in ledger_rows)
    ledger_dry_run_noop = all(
        row.get("ledger_status") in {"dry_run_noop", "blocked"}
        for row in ledger_rows
    )
    _backup_retention_execute_readiness_check(
        rows,
        group="ledger_safety",
        name="Ledger confirms no deletion",
        status="passed" if ledger_safe and ledger_dry_run_noop else "failed",
        reasons=[] if ledger_safe and ledger_dry_run_noop else ["ledger_deletion_evidence_or_missing"],
        observed=f"ledger_rows={len(ledger_rows)}",
        expected="dry-run ledger rows with did_delete_file=false",
        action="Rerun Task140 dry-run and inspect ledger.",
        hint="The ledger is safety evidence, not an execution instruction.",
    )
    _backup_retention_execute_readiness_check(
        rows,
        group="backup_pressure",
        name="Backup pressure present",
        status="passed" if pressure_known and pressure_present else "failed",
        reasons=[] if pressure_known and pressure_present else ["backup_pressure_missing"],
        observed=_backup_retention_execute_readiness_pressure_observed(task138_report),
        expected="near or over configured retention threshold",
        action="Rerun Task138 backup retention preview.",
        hint="Task141 needs retention pressure evidence before presenting execute for review.",
    )
    snapshot_rows = _backup_retention_execute_readiness_snapshot_rows(task140_report, snapshot_report)
    _backup_retention_execute_readiness_check(
        rows,
        group="post_apply_snapshot",
        name="Post-apply snapshot available",
        status="passed" if snapshot_rows else "warning",
        reasons=[] if snapshot_rows else ["post_apply_snapshot_missing"],
        observed=len(snapshot_rows),
        expected="snapshot rows available",
        action="Review Task140 post-apply snapshot.",
        hint="Missing snapshot does not delete files, but it weakens operator context.",
    )
    db_paper_status = _backup_retention_execute_readiness_db_paper_status(
        args,
        task140_report=task140_report,
        paper_value=paper_value,
        financial_count=financial_count,
    )
    _backup_retention_execute_readiness_check(rows, **db_paper_status)
    command = _backup_retention_execute_readiness_command(args, task140_report=task140_report)
    _backup_retention_execute_readiness_check(
        rows,
        group="execute_command",
        name="Future execute command generated",
        status="passed" if command else "failed",
        reasons=[] if command else ["future_execute_command_unavailable"],
        observed=command,
        expected="command template only",
        action="Do not run until manual approval.",
        hint="The board never runs this command.",
    )
    _backup_retention_execute_readiness_check(
        rows,
        group="manual_review",
        name="Manual approval still required",
        status="warning",
        reasons=["operator_manual_approval_required"],
        observed=True,
        expected=True,
        action="Complete the manual checklist before any execute command.",
        hint="Ready-for-review is not auto-approval.",
    )
    return rows


def _backup_retention_execute_readiness_ledger_rows(
    task140_report: dict[str, Any],
    ledger_report: dict[str, Any],
) -> list[dict[str, Any]]:
    rows = ledger_report.get("deletion_ledger_rows")
    if isinstance(rows, list):
        return [row for row in rows if isinstance(row, dict)]
    rows = task140_report.get("deletion_ledger_rows")
    if isinstance(rows, list):
        return [row for row in rows if isinstance(row, dict)]
    return []


def _backup_retention_execute_readiness_snapshot_rows(
    task140_report: dict[str, Any],
    snapshot_report: dict[str, Any],
) -> list[dict[str, Any]]:
    rows = snapshot_report.get("post_apply_snapshot_rows")
    if isinstance(rows, list):
        return [row for row in rows if isinstance(row, dict)]
    rows = task140_report.get("post_apply_snapshot_rows")
    if isinstance(rows, list):
        return [row for row in rows if isinstance(row, dict)]
    return []


def _backup_retention_execute_readiness_deleted_evidence(
    task140_report: dict[str, Any],
    ledger_rows: list[dict[str, Any]],
) -> bool:
    return bool(
        task140_report.get("files_deleted")
        or int(task140_report.get("deleted_count") or 0) > 0
        or int(task140_report.get("actual_reclaimed_bytes") or 0) > 0
        or any(row.get("did_delete_file") is True for row in ledger_rows)
    )


def _backup_retention_execute_readiness_blocker_counts(task140_report: dict[str, Any]) -> tuple[int, int]:
    expected = {
        "delete_count_limit_exceeded",
        "reclaim_size_limit_exceeded",
        "blocked_delete_count_limit_exceeded",
        "blocked_reclaim_limit_exceeded",
    }
    counts = task140_report.get("blocker_code_counts") or {}
    status_counts = task140_report.get("controlled_apply_status_counts") or {}
    blocker_rows = [
        row
        for row in task140_report.get("blocker_rows") or []
        if isinstance(row, dict)
    ]
    if blocker_rows:
        expected_count = 0
        unsafe_count = 0
        for row in blocker_rows:
            code = str(row.get("blocker_code") or row.get("controlled_apply_status") or "")
            if code in expected:
                expected_count += 1
            else:
                unsafe_count += 1
        return expected_count, unsafe_count
    expected_count = sum(int(counts.get(code, 0) or 0) for code in expected)
    expected_count += sum(int(status_counts.get(code, 0) or 0) for code in expected)
    unsafe_count = 0
    for key, value in {**counts, **status_counts}.items():
        if str(key) and str(key) not in expected and str(key) not in {
            "dry_run_eligible_for_delete",
            "deleted",
        }:
            unsafe_count += int(value or 0)
    return expected_count, unsafe_count


def _backup_retention_execute_readiness_backup_pressure(report: dict[str, Any]) -> tuple[bool, bool]:
    if not report:
        return False, False
    known = any(
        key in report
        for key in (
            "at_or_over_warning_threshold",
            "over_max_size_limit",
            "rotation_candidate_count",
            "recognized_backup_size_gb",
            "warning_threshold_size_gb",
        )
    )
    pressure = bool(
        report.get("at_or_over_warning_threshold")
        or report.get("over_max_size_limit")
        or int(report.get("rotation_candidate_count") or 0) > 0
    )
    if not pressure and report.get("recognized_backup_size_gb") is not None and report.get("warning_threshold_size_gb") is not None:
        pressure = float(report.get("recognized_backup_size_gb") or 0.0) >= float(report.get("warning_threshold_size_gb") or 0.0)
    return known, pressure


def _backup_retention_execute_readiness_pressure_observed(report: dict[str, Any]) -> str:
    if not report:
        return "missing"
    return (
        f"at_or_over_warning_threshold={report.get('at_or_over_warning_threshold')}; "
        f"over_max_size_limit={report.get('over_max_size_limit')}; "
        f"rotation_candidate_count={report.get('rotation_candidate_count')}; "
        f"recognized_backup_size_gb={report.get('recognized_backup_size_gb')}"
    )


def _backup_retention_execute_readiness_db_paper_status(
    args: argparse.Namespace,
    *,
    task140_report: dict[str, Any],
    paper_value: Any,
    financial_count: Any,
) -> dict[str, Any]:
    reasons: list[str] = []
    status = "passed"
    if paper_value is None or financial_count is None:
        return {
            "group": "db_paper_safety",
            "name": "DB and paper safety artifact evidence",
            "status": "warning",
            "reasons": ["db_paper_safety_unknown_from_artifacts"],
            "observed": "unknown_from_artifacts",
            "expected": f"paper_paused={args.backup_retention_require_paper_schedule_paused}; financial_reports_count={args.backup_retention_require_financial_reports_count}",
            "action": "Confirm financial_reports_count and paper schedule outside Task141 before execute.",
            "hint": "Task141 does not connect to DB or scheduler.",
        }
    if args.backup_retention_require_paper_schedule_paused and str(paper_value).casefold() not in {"paused", "pause", "true"}:
        status = "failed"
        reasons.append("paper_schedule_not_paused")
    if _as_int(financial_count) != args.backup_retention_require_financial_reports_count:
        status = "failed"
        reasons.append("financial_reports_count_mismatch")
    return {
        "group": "db_paper_safety",
        "name": "DB and paper safety artifact evidence",
        "status": status,
        "reasons": reasons,
        "observed": f"paper={paper_value}; financial_reports_count={financial_count}",
        "expected": f"paper_paused={args.backup_retention_require_paper_schedule_paused}; financial_reports_count={args.backup_retention_require_financial_reports_count}",
        "action": "Resolve DB/paper safety evidence before execute.",
        "hint": "Task141 only uses artifact fields.",
    }


def _backup_retention_execute_readiness_command(
    args: argparse.Namespace,
    *,
    task140_report: dict[str, Any],
) -> str:
    sha256 = str(task140_report.get("cleanup_manifest_sha256") or "")
    token = str(task140_report.get("confirmation_token_expected") or "")
    if not sha256 or not token:
        return ""
    output_dir = args.operator_resolution_chain_output_dir or Path("logs/financial_reports/task124_chain_preview")
    return "\n".join(
        [
            "python3 scripts/financial_official_source_evidence_assistant.py \\",
            "  --mode backup-retention-controlled-apply \\",
            f"  --operator-resolution-chain-output-dir {_bash_quote(str(output_dir))} \\",
            "  --backup-retention-execute true \\",
            f"  --backup-retention-expected-manifest-sha256 {sha256} \\",
            f"  --backup-retention-confirmation-token {token} \\",
            f"  --backup-retention-max-delete-count {args.backup_retention_proposed_max_delete_count} \\",
            f"  --backup-retention-max-delete-gb {args.backup_retention_proposed_max_delete_gb}",
        ]
    )


def _backup_retention_execute_readiness_blocker_rows(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return [
        {
            "blocker_id": f"backup_retention_execute_readiness_blocker:{row['board_check_id']}:{reason}",
            "board_check_id": row["board_check_id"],
            "check_group": row["check_group"],
            "blocker_code": reason,
            "blocker_severity": row["check_severity"],
            "operator_action": row["operator_action"],
            "safe_hint": row["safe_hint"],
        }
        for row in rows
        if row["check_status"] == "failed"
        for reason in (row["check_reason_codes"] or ["readiness_check_failed"])
    ]


def _backup_retention_execute_readiness_status(
    *,
    errors: list[dict[str, Any]],
    board_rows: list[dict[str, Any]],
) -> str:
    if errors:
        return "blocked_missing_required_artifacts"
    failed_reasons = [
        reason
        for row in board_rows
        if row.get("check_status") == "failed"
        for reason in row.get("check_reason_codes") or []
    ]
    priority = [
        ("task140_not_dry_run", "blocked_task140_not_dry_run"),
        ("files_already_deleted", "blocked_task140_deleted_files"),
        ("manifest_hash_missing_or_mismatch", "blocked_manifest_hash_missing"),
        ("confirmation_token_missing", "blocked_token_missing"),
        ("no_dry_run_eligible_rows", "blocked_no_dry_run_eligible_rows"),
        ("delete_limits_mismatch", "blocked_delete_limits_mismatch"),
        ("unsafe_blockers_present", "blocked_unsafe_blockers_present"),
        ("backup_pressure_missing", "blocked_backup_pressure_missing"),
        ("paper_schedule_not_paused", "blocked_db_or_paper_safety_unknown"),
        ("financial_reports_count_mismatch", "blocked_db_or_paper_safety_unknown"),
    ]
    for reason, status in priority:
        if reason in failed_reasons:
            return status
    if failed_reasons:
        return "blocked_execute_not_ready"
    return "ready_for_operator_execute_review"


def _build_backup_retention_execute_readiness_report(
    args: argparse.Namespace,
    *,
    task140_report: dict[str, Any],
    manifest_report: dict[str, Any],
    task138_report: dict[str, Any],
    ledger_report: dict[str, Any],
    snapshot_report: dict[str, Any],
    manifest_sha256: str,
    readiness_status: str,
    board_rows: list[dict[str, Any]],
    blocker_rows: list[dict[str, Any]],
    artifacts: dict[str, Path | None],
    warnings: list[dict[str, Any]],
    errors: list[dict[str, Any]],
) -> dict[str, Any]:
    warnings = _dedupe_messages(warnings)
    ready = readiness_status == "ready_for_operator_execute_review"
    status = "failed" if errors else "warning" if warnings or blocker_rows else "passed"
    expected_limit_blocker_count, unsafe_blocker_count = _backup_retention_execute_readiness_blocker_counts(task140_report)
    ledger_rows = _backup_retention_execute_readiness_ledger_rows(task140_report, ledger_report)
    snapshot_rows = _backup_retention_execute_readiness_snapshot_rows(task140_report, snapshot_report)
    recognized_snapshot_rows = [row for row in snapshot_rows if row.get("recognized_backup_file")]
    command = _backup_retention_execute_readiness_command(args, task140_report=task140_report)
    return {
        "status": status,
        "mode": "backup-retention-execute-readiness-board",
        "readiness_status": readiness_status,
        "ready_for_operator_execute_review": ready,
        "execute_allowed_by_board": False,
        "operator_manual_approval_required": True,
        "task140_status": task140_report.get("status"),
        "task140_execute_requested": task140_report.get("execute_requested"),
        "task140_deletion_execution_enabled": task140_report.get("deletion_execution_enabled"),
        "task140_deleted_count": task140_report.get("deleted_count", 0),
        "task140_files_deleted": task140_report.get("files_deleted", False),
        "task140_cleanup_executed": task140_report.get("cleanup_executed", False),
        "cleanup_manifest_sha256": task140_report.get("cleanup_manifest_sha256") or manifest_sha256,
        "task139_manifest_sha256": manifest_sha256,
        "confirmation_token_expected": task140_report.get("confirmation_token_expected", ""),
        "manifest_input_count": len(manifest_report.get("cleanup_manifest_rows") or []),
        "dry_run_eligible_count": task140_report.get("dry_run_eligible_count", 0),
        "blocked_count": task140_report.get("blocked_count", 0),
        "expected_limit_blocker_count": expected_limit_blocker_count,
        "unsafe_blocker_count": unsafe_blocker_count,
        "proposed_max_delete_count": args.backup_retention_proposed_max_delete_count,
        "proposed_max_delete_gb": args.backup_retention_proposed_max_delete_gb,
        "estimated_reclaimable_bytes": task140_report.get("estimated_reclaimable_bytes", 0),
        "estimated_reclaimable_gb": task140_report.get("estimated_reclaimable_gb", 0),
        "actual_reclaimed_bytes": task140_report.get("actual_reclaimed_bytes", 0),
        "actual_reclaimed_gb": task140_report.get("actual_reclaimed_gb", 0),
        "task138_recognized_backup_size_gb": task138_report.get("recognized_backup_size_gb"),
        "post_apply_backup_file_count": task140_report.get("post_apply_backup_file_count") or len(snapshot_rows),
        "post_apply_recognized_backup_file_count": task140_report.get("post_apply_recognized_backup_file_count") or len(recognized_snapshot_rows),
        "post_apply_recognized_backup_size_gb": task140_report.get("post_apply_recognized_backup_size_gb")
        or _bytes_to_gb(sum(int(row.get("size_bytes") or 0) for row in recognized_snapshot_rows)),
        "future_execute_command": command,
        "board_check_count": len(board_rows),
        "passed_check_count": sum(row["check_status"] == "passed" for row in board_rows),
        "warning_check_count": sum(row["check_status"] == "warning" for row in board_rows),
        "failed_check_count": sum(row["check_status"] == "failed" for row in board_rows),
        "blocker_row_count": len(blocker_rows),
        "board_rows": board_rows,
        "blocker_rows": blocker_rows,
        "warnings": warnings,
        "errors": errors,
        "artifacts": {key: _path_value(path) for key, path in artifacts.items()},
        "next_steps": _next_steps("backup-retention-execute-readiness-board", status),
        **_backup_retention_safety_flags(),
    }


