def _write_backup_retention_execute_readiness_outputs(
    report: dict[str, Any],
    *,
    artifacts: dict[str, Path | None],
) -> None:
    if artifacts["readiness_json"] is not None:
        write_json_report(report, artifacts["readiness_json"])
    if artifacts["readiness_csv"] is not None:
        _write_flat_csv([_backup_retention_execute_readiness_summary_row(report)], BACKUP_RETENTION_EXECUTE_READINESS_FIELDS, artifacts["readiness_csv"])
    if artifacts["readiness_markdown"] is not None:
        write_backup_retention_execute_readiness_markdown(report, artifacts["readiness_markdown"])
    if artifacts["board_json"] is not None:
        write_json_report(_backup_retention_execute_readiness_board_report(report), artifacts["board_json"])
    if artifacts["board_csv"] is not None:
        _write_flat_csv(report["board_rows"], BACKUP_RETENTION_EXECUTE_READINESS_BOARD_FIELDS, artifacts["board_csv"])
    if artifacts["blockers_json"] is not None:
        write_json_report(_backup_retention_execute_readiness_blockers_report(report), artifacts["blockers_json"])
    if artifacts["blockers_csv"] is not None:
        _write_flat_csv(report["blocker_rows"], BACKUP_RETENTION_EXECUTE_READINESS_BLOCKER_FIELDS, artifacts["blockers_csv"])


def _first_present(row: dict[str, Any], keys: tuple[str, ...]) -> Any:
    for key in keys:
        if key in row and row.get(key) is not None:
            return row.get(key)
    return None


def _count_values(rows: list[dict[str, Any]], field: str) -> dict[str, int]:
    counts: dict[str, int] = {}
    for row in rows:
        value = str(row.get(field) or "")
        counts[value] = counts.get(value, 0) + 1
    return counts


def _dedupe_messages(messages: list[dict[str, Any]]) -> list[dict[str, Any]]:
    seen: set[tuple[tuple[str, str], ...]] = set()
    output: list[dict[str, Any]] = []
    for message in messages:
        key = tuple(sorted((str(field), str(value)) for field, value in message.items()))
        if key not in seen:
            seen.add(key)
            output.append(message)
    return output


def run_financial_document_fetch_plan_preview(args: argparse.Namespace) -> dict[str, Any]:
    warnings: list[dict[str, Any]] = []
    errors = _financial_document_fetch_plan_config_errors(args)
    retention_report, retention_path, retention_errors = _load_financial_document_fetch_retention_report(
        args,
        warnings=warnings,
    )
    errors.extend(retention_errors)
    retention_paths = _financial_document_fetch_retention_paths(retention_report)
    artifacts = _financial_document_fetch_plan_artifacts(args)
    summary_report, summary_path = _load_financial_document_fetch_optional_report(
        _financial_document_fetch_optional_paths(
            args.document_intake_draft_gate_summary_input,
            args.operator_resolution_chain_output_dir,
            (
                OPERATOR_RESOLUTION_CHAIN_PREVIEW_ARTIFACT_NAMES["document_intake_draft_gate_summary_json"],
                "document_intake_draft_gate_summary_task122.json",
            ),
        ),
        role="document_intake_draft_gate_summary",
        warnings=warnings,
    )
    gate_report, gate_path = _load_financial_document_fetch_optional_report(
        _financial_document_fetch_optional_paths(
            args.document_intake_draft_gate_input,
            args.operator_resolution_chain_output_dir,
            (
                OPERATOR_RESOLUTION_CHAIN_PREVIEW_ARTIFACT_NAMES["document_intake_draft_gate_json"],
                "document_intake_draft_gate_task122.json",
            ),
        ),
        role="document_intake_draft_gate",
        warnings=warnings,
    )
    board_report, board_path = _load_financial_document_fetch_optional_report(
        _financial_document_fetch_optional_paths(
            args.operator_resolution_chain_review_board_input,
            args.operator_resolution_chain_output_dir,
            (OPERATOR_RESOLUTION_CHAIN_REVIEW_BOARD_ARTIFACT_NAMES["board_json"],),
        ),
        role="operator_resolution_chain_review_board",
        warnings=warnings,
    )
    protected_inputs = [
        path
        for path in (retention_path, summary_path, gate_path, board_path)
        if path is not None
    ]
    errors.extend(
        _financial_document_fetch_plan_output_errors(
            args,
            artifacts=artifacts,
            protected_inputs=protected_inputs,
            retention_paths=retention_paths,
        )
    )
    source_rows = _financial_document_fetch_candidate_rows(
        args,
        summary_report=summary_report,
        gate_report=gate_report,
        board_report=board_report,
    )
    if not source_rows:
        warnings.append({"message": "financial_document_fetch_plan_no_candidate_rows"})
    plan_rows = [
        _build_financial_document_fetch_plan_row(
            args,
            row,
            retention_report=retention_report,
            retention_paths=retention_paths,
        )
        for row in source_rows
    ]
    _apply_financial_document_fetch_download_cap(args, plan_rows)
    manifest_rows = copy.deepcopy(plan_rows)
    blocker_rows = _build_financial_document_fetch_blocker_rows(plan_rows)
    report = _build_financial_document_fetch_plan_report(
        args,
        plan_rows=plan_rows,
        manifest_rows=manifest_rows,
        blocker_rows=blocker_rows,
        retention_report=retention_report,
        retention_path=retention_path,
        summary_path=summary_path,
        gate_path=gate_path,
        board_path=board_path,
        artifacts=artifacts,
        warnings=warnings,
        errors=errors,
    )
    if not errors:
        try:
            if artifacts["fetch_plan_json"] is not None:
                write_json_report(report, artifacts["fetch_plan_json"])
            if artifacts["fetch_plan_csv"] is not None:
                _write_flat_csv(plan_rows, FINANCIAL_DOCUMENT_FETCH_PLAN_FIELDS, artifacts["fetch_plan_csv"])
            if artifacts["fetch_plan_markdown"] is not None:
                write_financial_document_fetch_plan_markdown(report, artifacts["fetch_plan_markdown"])
            if artifacts["download_manifest_json"] is not None:
                write_json_report(_financial_document_download_manifest_report(report), artifacts["download_manifest_json"])
            if artifacts["download_manifest_csv"] is not None:
                _write_flat_csv(
                    manifest_rows,
                    FINANCIAL_DOCUMENT_DOWNLOAD_MANIFEST_FIELDS,
                    artifacts["download_manifest_csv"],
                )
            if artifacts["fetch_blockers_json"] is not None:
                write_json_report(_financial_document_fetch_blockers_report(report), artifacts["fetch_blockers_json"])
            if artifacts["fetch_blockers_csv"] is not None:
                _write_flat_csv(blocker_rows, FINANCIAL_DOCUMENT_FETCH_BLOCKER_FIELDS, artifacts["fetch_blockers_csv"])
        except OSError as exc:
            report["status"] = "failed"
            report["errors"] = [*report["errors"], {"message": str(exc)}]
    return report


def _financial_document_fetch_plan_config_errors(args: argparse.Namespace) -> list[dict[str, Any]]:
    errors: list[dict[str, Any]] = []
    if args.financial_document_fetch_max_planned_downloads < 0:
        errors.append({"message": "invalid_financial_document_fetch_plan_value:financial_document_fetch_max_planned_downloads"})
    if args.financial_document_fetch_max_single_file_mb <= 0:
        errors.append({"message": "invalid_financial_document_fetch_plan_value:financial_document_fetch_max_single_file_mb"})
    return errors


def _load_financial_document_fetch_retention_report(
    args: argparse.Namespace,
    *,
    warnings: list[dict[str, Any]],
) -> tuple[dict[str, Any], Path | None, list[dict[str, Any]]]:
    explicit = args.document_artifact_retention_input
    auto_path = (
        args.operator_resolution_chain_output_dir / DOCUMENT_ARTIFACT_RETENTION_ARTIFACT_NAMES["policy_json"]
        if args.operator_resolution_chain_output_dir is not None
        else None
    )
    path = explicit or (auto_path if auto_path is not None and auto_path.is_file() else None)
    if path is None:
        warnings.append({"message": "document_artifact_retention_policy_missing_using_safe_defaults"})
        return _financial_document_fetch_safe_default_retention_report(), None, []
    try:
        report = _load_json_object(path)
    except (OSError, ValueError, json.JSONDecodeError):
        return _financial_document_fetch_safe_default_retention_report(), path, [
            {"message": "document_artifact_retention_input_invalid", "path": str(path)}
        ]
    if report.get("mode") != "financial-document-artifact-retention-preview":
        return _financial_document_fetch_safe_default_retention_report(), path, [
            {"message": "document_artifact_retention_input_invalid", "path": str(path)}
        ]
    return report, path, []


def _financial_document_fetch_safe_default_retention_report() -> dict[str, Any]:
    paths = DOCUMENT_ARTIFACT_RETENTION_DEFAULT_PATHS
    return {
        "mode": "financial-document-artifact-retention-preview",
        "status": "warning",
        "disk_guard_status": "blocked",
        "download_allowed": False,
        "future_extraction_allowed": False,
        "guard_reason_codes": ["document_artifact_retention_policy_missing_using_safe_defaults"],
        "policy_rows": [
            {"artifact_class": "raw_report_cache", "path_role": "raw_cache", "default_path": str(paths["raw_cache"])},
            {
                "artifact_class": "debug_quarantine",
                "path_role": "debug_quarantine",
                "default_path": str(paths["debug_quarantine"]),
            },
            {
                "artifact_class": "extraction_artifacts",
                "path_role": "extraction_artifacts",
                "default_path": str(paths["extraction_artifacts"]),
            },
            {
                "artifact_class": "hash_manifest",
                "path_role": "hash_manifest",
                "default_path": str(paths["artifact_root"] / "hash_manifest"),
            },
        ],
    }


def _financial_document_fetch_retention_paths(report: dict[str, Any]) -> dict[str, Path]:
    defaults = {
        "raw_cache": DOCUMENT_ARTIFACT_RETENTION_DEFAULT_PATHS["raw_cache"],
        "debug_quarantine": DOCUMENT_ARTIFACT_RETENTION_DEFAULT_PATHS["debug_quarantine"],
        "extraction_artifacts": DOCUMENT_ARTIFACT_RETENTION_DEFAULT_PATHS["extraction_artifacts"],
        "hash_manifest": DOCUMENT_ARTIFACT_RETENTION_DEFAULT_PATHS["artifact_root"] / "hash_manifest",
    }
    for row in report.get("policy_rows") or []:
        if not isinstance(row, dict):
            continue
        path_role = str(row.get("path_role") or "")
        default_path = str(row.get("default_path") or "")
        if path_role in defaults and default_path:
            defaults[path_role] = Path(default_path)
    return defaults


def _financial_document_fetch_plan_artifacts(args: argparse.Namespace) -> dict[str, Path | None]:
    output_dir = args.operator_resolution_chain_output_dir
    overrides = {
        "fetch_plan_json": args.financial_document_fetch_plan_output,
        "fetch_plan_csv": args.financial_document_fetch_plan_csv_output,
        "fetch_plan_markdown": args.financial_document_fetch_plan_markdown_output,
        "download_manifest_json": args.financial_document_download_manifest_output,
        "download_manifest_csv": args.financial_document_download_manifest_csv_output,
        "fetch_blockers_json": args.financial_document_fetch_blockers_output,
        "fetch_blockers_csv": args.financial_document_fetch_blockers_csv_output,
    }
    return {
        key: overrides[key] or (output_dir / file_name if output_dir is not None else None)
        for key, file_name in FINANCIAL_DOCUMENT_FETCH_PLAN_ARTIFACT_NAMES.items()
    }


def _financial_document_fetch_optional_paths(
    explicit: Path | None,
    output_dir: Path | None,
    filenames: Sequence[str],
) -> list[Path]:
    paths: list[Path] = []
    if explicit is not None:
        paths.append(explicit)
    if output_dir is not None:
        paths.extend(output_dir / name for name in filenames)
    deduplicated: list[Path] = []
    for path in paths:
        if not any(_paths_equal(path, existing) for existing in deduplicated):
            deduplicated.append(path)
    return deduplicated


def _load_financial_document_fetch_optional_report(
    paths: list[Path],
    *,
    role: str,
    warnings: list[dict[str, Any]],
) -> tuple[dict[str, Any], Path | None]:
    for path in paths:
        if not path.is_file():
            if paths and path == paths[0]:
                warnings.append({"message": f"financial_document_fetch_optional_artifact_unreadable:{role}", "path": str(path)})
            continue
        try:
            return _load_json_object(path), path
        except (OSError, ValueError, json.JSONDecodeError):
            warnings.append({"message": f"financial_document_fetch_optional_artifact_unreadable:{role}", "path": str(path)})
    return {}, None


def _financial_document_fetch_plan_output_errors(
    args: argparse.Namespace,
    *,
    artifacts: dict[str, Path | None],
    protected_inputs: list[Path],
    retention_paths: dict[str, Path],
) -> list[dict[str, Any]]:
    outputs = [path for path in [*artifacts.values(), args.json_output, args.markdown_output] if path is not None]
    for index, path in enumerate(outputs):
        if any(_paths_equal(path, other) for other in outputs[index + 1 :]):
            return [{"message": "financial_document_fetch_plan_output_must_not_equal_input"}]
    for path in outputs:
        if not _financial_document_fetch_plan_output_path_is_safe(
            path,
            protected_inputs=protected_inputs,
            retention_paths=retention_paths,
        ):
            return [{"message": "financial_document_fetch_plan_output_must_not_equal_input"}]
    return []


def _financial_document_fetch_plan_output_path_is_safe(
    output_path: Path,
    *,
    protected_inputs: Sequence[Path],
    retention_paths: dict[str, Path],
) -> bool:
    if any(_paths_equal(output_path, path) for path in protected_inputs):
        return False
    return not any(
        _path_is_within(output_path, retention_paths[path_role])
        for path_role in ("raw_cache", "debug_quarantine", "hash_manifest")
    )


def _financial_document_fetch_candidate_rows(
    args: argparse.Namespace,
    *,
    summary_report: dict[str, Any],
    gate_report: dict[str, Any],
    board_report: dict[str, Any],
) -> list[dict[str, Any]]:
    summary_rows = summary_report.get("draft_gate_summary_rows") or []
    gate_rows = gate_report.get("required_issuers") or []
    board_rows = board_report.get("rows") or []
    board_by_key = {
        _financial_document_fetch_candidate_key(row): row
        for row in board_rows
        if isinstance(row, dict)
    }
    if isinstance(summary_rows, list) and any(isinstance(row, dict) for row in summary_rows):
        return [
            _financial_document_fetch_summary_candidate(args, row, board_by_key=board_by_key)
            for row in summary_rows
            if isinstance(row, dict)
        ]
    if isinstance(gate_rows, list) and any(isinstance(row, dict) for row in gate_rows):
        return [
            _financial_document_fetch_gate_candidate(args, row, gate_report=gate_report, board_by_key=board_by_key)
            for row in gate_rows
            if isinstance(row, dict)
        ]
    return [
        _financial_document_fetch_board_candidate(args, row)
        for row in board_rows
        if isinstance(row, dict)
    ]


def _financial_document_fetch_candidate_key(row: dict[str, Any]) -> str:
    resolution_id = str(row.get("resolution_id") or "")
    if resolution_id:
        return f"resolution:{resolution_id}"
    return "company:" + str(row.get("canonical_company_id") or row.get("company_id") or "")


def _financial_document_fetch_board_match(
    row: dict[str, Any],
    *,
    board_by_key: dict[str, dict[str, Any]],
) -> dict[str, Any]:
    return board_by_key.get(_financial_document_fetch_candidate_key(row)) or {}


def _financial_document_fetch_identity(row: dict[str, Any], board: dict[str, Any]) -> dict[str, Any]:
    return {
        "resolution_id": row.get("resolution_id") or board.get("resolution_id") or "",
        "company_id": row.get("company_id") or board.get("company_id") or "",
        "company_name": row.get("company_name") or board.get("company_name") or "",
        "canonical_company_id": row.get("canonical_company_id") or board.get("canonical_company_id") or row.get("company_id") or "",
        "canonical_company_name": row.get("canonical_company_name") or board.get("canonical_company_name") or row.get("company_name") or "",
    }


def _financial_document_fetch_summary_candidate(
    args: argparse.Namespace,
    row: dict[str, Any],
    *,
    board_by_key: dict[str, dict[str, Any]],
) -> dict[str, Any]:
    board = _financial_document_fetch_board_match(row, board_by_key=board_by_key)
    strict_ready = bool(
        row.get("draft_row_status") == "draft_ready_for_future_extraction_preview"
        and _as_bool(row.get("has_exact_target_document"))
        and _as_bool(row.get("gate_passed"))
        and _as_bool(row.get("ready_for_value_extraction"))
    )
    return {
        **_financial_document_fetch_identity(row, board),
        "candidate_source": "document_intake_draft_gate_summary",
        "target_reporting_period": row.get("target_reporting_period") or args.financial_document_fetch_target_period,
        "required_report_type": row.get("required_report_type") or args.financial_document_fetch_required_report_type,
        "required_standard": row.get("required_standard") or args.financial_document_fetch_required_standard,
        "source_document_url": row.get("draft_document_url") or "",
        "source_document_title": row.get("draft_document_title") or "",
        "source_document_size_bytes_expected": _financial_document_fetch_expected_size(row),
        "source_document_consolidated": True if strict_ready else _as_bool(row.get("source_document_consolidated")),
        "document_kind": row.get("document_kind") or "",
        "document_period_year": row.get("document_period_year") or "",
        "document_period_status": row.get("document_period_status") or "",
        "report_type_match_status": row.get("report_type_match_status") or "",
        "accounting_standard_match_status": row.get("accounting_standard_match_status") or "",
        "document_gate_ready": bool(row.get("draft_document_url") and _as_bool(row.get("has_exact_target_document"))),
        "source_gate_ready": strict_ready,
        "document_gate_status": row.get("validation_status") or row.get("draft_row_status") or "",
        "source_gate_status": row.get("gate_status") or "",
        "trusted_source_hosts": _financial_document_fetch_list(board.get("trusted_source_hosts")),
        "historical_fallback_url": board.get("latest_historical_document_url") or "",
        "historical_fallback_only": _financial_document_fetch_historical_fallback_only(row, board),
    }


def _financial_document_fetch_gate_candidate(
    args: argparse.Namespace,
    row: dict[str, Any],
    *,
    gate_report: dict[str, Any],
    board_by_key: dict[str, dict[str, Any]],
) -> dict[str, Any]:
    board = _financial_document_fetch_board_match(row, board_by_key=board_by_key)
    gate_ready = bool(row.get("gate_status") == "passed" and gate_report.get("ready_for_value_extraction"))
    document_url = row.get("document_url") or ""
    return {
        **_financial_document_fetch_identity(row, board),
        "candidate_source": "document_intake_draft_gate",
        "target_reporting_period": row.get("target_reporting_period") or args.financial_document_fetch_target_period,
        "required_report_type": row.get("required_report_type") or args.financial_document_fetch_required_report_type,
        "required_standard": row.get("required_standard") or args.financial_document_fetch_required_standard,
        "source_document_url": document_url,
        "source_document_title": row.get("document_title") or "",
        "source_document_size_bytes_expected": _financial_document_fetch_expected_size(row),
        "source_document_consolidated": _as_bool(row.get("source_document_consolidated")),
        "document_kind": row.get("document_kind") or "",
        "document_period_year": row.get("document_period_year") or "",
        "document_period_status": row.get("document_period_status") or "",
        "report_type_match_status": row.get("report_type_match_status") or "",
        "accounting_standard_match_status": row.get("accounting_standard_match_status") or "",
        "document_gate_ready": bool(document_url and gate_ready),
        "source_gate_ready": gate_ready,
        "document_gate_status": row.get("gate_status") or "",
        "source_gate_status": row.get("gate_status") or "",
        "trusted_source_hosts": _financial_document_fetch_list(board.get("trusted_source_hosts")),
        "historical_fallback_url": board.get("latest_historical_document_url") or "",
        "historical_fallback_only": _financial_document_fetch_historical_fallback_only(row, board),
    }


def _financial_document_fetch_board_candidate(args: argparse.Namespace, row: dict[str, Any]) -> dict[str, Any]:
    trusted_hosts = _financial_document_fetch_list(row.get("trusted_source_hosts"))
    gate_ready = bool(
        row.get("overall_status") == "ready_for_future_extraction_preview"
        and row.get("draft_gate_status") == "draft_ready_for_future_extraction_preview"
        and _as_bool(row.get("ready_for_value_extraction"))
        and trusted_hosts
    )
    return {
        **_financial_document_fetch_identity(row, {}),
        "candidate_source": "operator_resolution_chain_review_board",
        "target_reporting_period": row.get("target_reporting_period") or args.financial_document_fetch_target_period,
        "required_report_type": row.get("required_report_type") or args.financial_document_fetch_required_report_type,
        "required_standard": row.get("required_standard") or args.financial_document_fetch_required_standard,
        "source_document_url": row.get("operator_fill_exact_document_url") if gate_ready else "",
        "source_document_title": row.get("operator_fill_document_title") or "",
        "source_document_size_bytes_expected": _financial_document_fetch_expected_size(row),
        "source_document_consolidated": _as_bool(row.get("source_document_consolidated")),
        "document_kind": row.get("document_kind") or ("exact_report_document" if gate_ready else ""),
        "document_period_year": row.get("operator_fill_report_period") or row.get("target_reporting_period") or "",
        "document_period_status": row.get("document_period_status") or ("target_period" if gate_ready else ""),
        "report_type_match_status": row.get("report_type_match_status") or ("annual_match" if gate_ready else ""),
        "accounting_standard_match_status": row.get("accounting_standard_match_status") or ("standard_match" if gate_ready else ""),
        "document_gate_ready": gate_ready,
        "source_gate_ready": gate_ready,
        "document_gate_status": row.get("draft_gate_status") or "",
        "source_gate_status": row.get("overall_status") or "",
        "trusted_source_hosts": trusted_hosts,
        "historical_fallback_url": row.get("latest_historical_document_url") or "",
        "historical_fallback_only": _financial_document_fetch_historical_fallback_only(row, row),
    }


def _financial_document_fetch_historical_fallback_only(row: dict[str, Any], board: dict[str, Any]) -> bool:
    fallback_status = str(row.get("draft_fallback_status") or row.get("fallback_status") or "")
    blockers = _financial_document_fetch_list(row.get("blocked_reason_codes"))
    historical_url = str(board.get("latest_historical_document_url") or "")
    document_url = str(row.get("draft_document_url") or row.get("document_url") or row.get("operator_fill_exact_document_url") or "")
    return bool(
        fallback_status not in {"", "not_fallback"}
        or "historical_fallback_not_target_evidence" in blockers
        or "historical_fallback_url_used_as_exact_document" in blockers
        or (historical_url and (not document_url or document_url == historical_url))
    )


def _financial_document_fetch_expected_size(row: dict[str, Any]) -> int | None:
    for field in (
        "source_document_size_bytes_expected",
        "expected_size_bytes",
        "document_size_bytes_expected",
        "document_size_bytes",
    ):
        value = _as_int(row.get(field))
        if value is not None and value >= 0:
            return value
    return None


def _build_financial_document_fetch_plan_row(
    args: argparse.Namespace,
    candidate: dict[str, Any],
    *,
    retention_report: dict[str, Any],
    retention_paths: dict[str, Path],
) -> dict[str, Any]:
    source_url = str(candidate.get("source_document_url") or "")
    sha256 = hashlib.sha256(source_url.encode("utf-8")).hexdigest() if source_url else ""
    safe_company = _financial_document_fetch_safe_path_component(
        candidate.get("canonical_company_id") or candidate.get("company_id"),
        fallback="unknown_company",
    )
    safe_period = _financial_document_fetch_safe_path_component(
        candidate.get("target_reporting_period"),
        fallback="unknown_period",
    )
    file_component = sha256 or "missing_exact_document_url"
    warnings: list[str] = []
    if candidate.get("source_document_size_bytes_expected") is None:
        warnings.append("single_file_size_unknown_requires_future_pre_write_check")
    status, reasons = _financial_document_fetch_plan_status(args, candidate, retention_report=retention_report)
    ready = status == "eligible_for_future_controlled_download"
    disk_guard_status = str(retention_report.get("disk_guard_status") or "blocked")
    fetch_plan_id = f"financial_document_fetch_plan:{safe_company}:{safe_period}:{file_component}"
    return {
        "fetch_plan_id": fetch_plan_id,
        "resolution_id": candidate.get("resolution_id") or "",
        "company_id": candidate.get("company_id") or "",
        "company_name": candidate.get("company_name") or "",
        "canonical_company_id": candidate.get("canonical_company_id") or candidate.get("company_id") or "",
        "canonical_company_name": candidate.get("canonical_company_name") or candidate.get("company_name") or "",
        "candidate_source": candidate.get("candidate_source") or "",
        "target_reporting_period": candidate.get("target_reporting_period") or "",
        "required_report_type": candidate.get("required_report_type") or "",
        "required_standard": candidate.get("required_standard") or "",
        "required_consolidated": args.financial_document_fetch_required_consolidated,
        "source_document_url": source_url,
        "source_document_url_sha256": sha256,
        "source_document_title": candidate.get("source_document_title") or "",
        "source_document_size_bytes_expected": candidate.get("source_document_size_bytes_expected"),
        "source_document_consolidated": bool(candidate.get("source_document_consolidated")),
        "document_kind": candidate.get("document_kind") or "",
        "document_period_year": candidate.get("document_period_year") or "",
        "document_period_status": candidate.get("document_period_status") or "",
        "report_type_match_status": candidate.get("report_type_match_status") or "",
        "accounting_standard_match_status": candidate.get("accounting_standard_match_status") or "",
        "document_gate_status": candidate.get("document_gate_status") or "",
        "source_gate_status": candidate.get("source_gate_status") or "",
        "trusted_source_hosts": candidate.get("trusted_source_hosts") or [],
        "historical_fallback_url": candidate.get("historical_fallback_url") or "",
        "historical_fallback_allowed_as_target_evidence": False,
        "disk_guard_status": disk_guard_status,
        "disk_guard_reason_codes": list(retention_report.get("guard_reason_codes") or []),
        "fetch_plan_status": status,
        "fetch_plan_reason_codes": reasons,
        "fetch_plan_warnings": warnings,
        "ready_for_future_download": ready,
        "download_attempt_allowed_now": bool(ready and disk_guard_status == "passed"),
        "future_pre_write_size_check_required": candidate.get("source_document_size_bytes_expected") is None,
        "planned_raw_document_path": str(retention_paths["raw_cache"] / safe_company / safe_period / f"{file_component}.downloaded.pdf"),
        "planned_hash_manifest_path": str(retention_paths["hash_manifest"] / safe_company / safe_period / f"{file_component}.json"),
        "planned_debug_quarantine_dir": str(retention_paths["debug_quarantine"] / safe_company / safe_period),
        "planned_extraction_artifact_prefix": str(retention_paths["extraction_artifacts"] / safe_company / safe_period),
        "actual_document_sha256_required_after_download": True,
        **_financial_document_fetch_plan_safety_flags(),
    }


def _financial_document_fetch_plan_status(
    args: argparse.Namespace,
    candidate: dict[str, Any],
    *,
    retention_report: dict[str, Any],
) -> tuple[str, list[str]]:
    source_url = str(candidate.get("source_document_url") or "")
    if retention_report.get("disk_guard_status") == "blocked":
        return "blocked_disk_guard", list(retention_report.get("guard_reason_codes") or ["disk_guard_blocked"])
    if candidate.get("historical_fallback_only"):
        return "blocked_historical_fallback_only", ["historical_fallback_not_target_evidence"]
    if not source_url:
        return "blocked_missing_exact_document_url", ["missing_exact_document_url"]
    if not _financial_document_fetch_url_is_http(source_url):
        return "blocked_invalid_document_url", ["invalid_document_url"]
    if str(candidate.get("target_reporting_period") or "") != str(args.financial_document_fetch_target_period):
        return "blocked_wrong_period", ["wrong_period"]
    if candidate.get("document_period_status") not in {"", "target_period"}:
        return "blocked_wrong_period", ["wrong_period"]
    if str(candidate.get("required_report_type") or "") != str(args.financial_document_fetch_required_report_type):
        return "blocked_wrong_report_type", ["wrong_report_type"]
    if candidate.get("report_type_match_status") not in {"", "annual_match"}:
        return "blocked_wrong_report_type", ["wrong_report_type"]
    if str(candidate.get("required_standard") or "") != str(args.financial_document_fetch_required_standard):
        return "blocked_wrong_accounting_standard", ["wrong_accounting_standard"]
    if candidate.get("accounting_standard_match_status") not in {"", "standard_match"}:
        return "blocked_wrong_accounting_standard", ["wrong_accounting_standard"]
    if args.financial_document_fetch_required_consolidated and not candidate.get("source_document_consolidated"):
        return "blocked_non_consolidated", ["non_consolidated"]
    if not candidate.get("document_gate_ready"):
        return "blocked_document_gate_not_ready", ["document_gate_not_ready"]
    if not candidate.get("source_gate_ready"):
        return "blocked_source_gate_not_ready", ["source_gate_not_ready"]
    size = candidate.get("source_document_size_bytes_expected")
    if size is not None and size > args.financial_document_fetch_max_single_file_mb * 1024**2:
        return "blocked_single_file_size_exceeded", ["single_file_size_exceeded"]
    return "eligible_for_future_controlled_download", []


def _apply_financial_document_fetch_download_cap(args: argparse.Namespace, rows: list[dict[str, Any]]) -> None:
    eligible = sorted(
        (row for row in rows if row.get("fetch_plan_status") == "eligible_for_future_controlled_download"),
        key=lambda row: (
            str(row.get("canonical_company_id") or row.get("company_id") or ""),
            str(row.get("resolution_id") or ""),
            str(row.get("source_document_url") or ""),
        ),
    )
    for row in eligible[args.financial_document_fetch_max_planned_downloads :]:
        row["fetch_plan_status"] = "blocked_max_planned_downloads_exceeded"
        row["fetch_plan_reason_codes"] = ["max_planned_downloads_exceeded"]
        row["ready_for_future_download"] = False
        row["download_attempt_allowed_now"] = False


def _build_financial_document_fetch_blocker_rows(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    blockers: list[dict[str, Any]] = []
    for row in rows:
        if row.get("fetch_plan_status") == "eligible_for_future_controlled_download":
            continue
        reason_codes = row.get("fetch_plan_reason_codes") or [row.get("fetch_plan_status")]
        for reason in reason_codes:
            blockers.append(
                {
                    "fetch_plan_id": row.get("fetch_plan_id"),
                    "resolution_id": row.get("resolution_id"),
                    "company_id": row.get("company_id"),
                    "company_name": row.get("company_name"),
                    "canonical_company_id": row.get("canonical_company_id"),
                    "canonical_company_name": row.get("canonical_company_name"),
                    "fetch_plan_status": row.get("fetch_plan_status"),
                    "blocker_code": reason,
                    "blocker_severity": "high",
                    "blocker_next_action": _financial_document_fetch_blocker_next_action(str(reason)),
                }
            )
    return blockers


def _financial_document_fetch_blocker_next_action(code: str) -> str:
    if code in {"missing_exact_document_url", "historical_fallback_not_target_evidence"}:
        return "Provide an exact official target-period annual IFRS document URL and rerun the strict preview chain."
    if code in {"filesystem_stat_unavailable", "free_disk_below_minimum_gb", "free_disk_below_minimum_percent"}:
        return "Rerun Task132 and review filesystem capacity before any future download."
    if "size" in code or "raw_cache" in code or "quarantine" in code:
        return "Review Task132 inspect-only cleanup guidance and storage limits before any future download."
    return "Review strict document/source gate diagnostics and rerun the preview chain."


def _build_financial_document_fetch_plan_report(
    args: argparse.Namespace,
    *,
    plan_rows: list[dict[str, Any]],
    manifest_rows: list[dict[str, Any]],
    blocker_rows: list[dict[str, Any]],
    retention_report: dict[str, Any],
    retention_path: Path | None,
    summary_path: Path | None,
    gate_path: Path | None,
    board_path: Path | None,
    artifacts: dict[str, Path | None],
    warnings: list[dict[str, Any]],
    errors: list[dict[str, Any]],
) -> dict[str, Any]:
    row_warning_count = sum(len(row.get("fetch_plan_warnings") or []) for row in plan_rows)
    eligible_count = sum(1 for row in plan_rows if row.get("fetch_plan_status") == "eligible_for_future_controlled_download")
    blocked_count = len(plan_rows) - eligible_count
    status = "failed" if errors else "warning" if warnings or blocked_count or row_warning_count else "passed"
    return {
        "status": status,
        "mode": "financial-document-fetch-plan-preview",
        "target_reporting_period": str(args.financial_document_fetch_target_period),
        "required_report_type": str(args.financial_document_fetch_required_report_type),
        "required_standard": str(args.financial_document_fetch_required_standard),
        "required_consolidated": args.financial_document_fetch_required_consolidated,
        "max_planned_downloads": args.financial_document_fetch_max_planned_downloads,
        "max_single_file_mb": args.financial_document_fetch_max_single_file_mb,
        "document_artifact_retention_input": _path_value(retention_path),
        "document_intake_draft_gate_summary_input": _path_value(summary_path),
        "document_intake_draft_gate_input": _path_value(gate_path),
        "operator_resolution_chain_review_board_input": _path_value(board_path),
        "disk_guard_status": retention_report.get("disk_guard_status") or "blocked",
        "download_allowed_by_disk_guard": bool(retention_report.get("download_allowed")),
        "future_extraction_allowed_by_disk_guard": bool(retention_report.get("future_extraction_allowed")),
        "disk_guard_reason_codes": list(retention_report.get("guard_reason_codes") or []),
        "fetch_plan_row_count": len(plan_rows),
        "fetch_plan_eligible_count": eligible_count,
        "fetch_plan_blocked_count": blocked_count,
        "download_attempt_allowed_now_count": sum(1 for row in plan_rows if row.get("download_attempt_allowed_now")),
        "download_manifest_row_count": len(manifest_rows),
        "fetch_blocker_row_count": len(blocker_rows),
        "fetch_plan_status_counts": _count_by_key(plan_rows, "fetch_plan_status"),
        "fetch_blocker_counts": _count_by_key(blocker_rows, "blocker_code"),
        "fetch_plan_rows": plan_rows,
        "download_manifest_rows": manifest_rows,
        "fetch_blocker_rows": blocker_rows,
        "artifacts": {key: _path_value(path) for key, path in artifacts.items()},
        "warnings": warnings,
        "errors": errors,
        "next_steps": _next_steps("financial-document-fetch-plan-preview", status),
        **_financial_document_fetch_plan_safety_flags(),
    }


def _financial_document_download_manifest_report(report: dict[str, Any]) -> dict[str, Any]:
    return {
        "status": report["status"],
        "mode": "financial-document-download-manifest-preview",
        "disk_guard_status": report["disk_guard_status"],
        "download_manifest_row_count": report["download_manifest_row_count"],
        "download_manifest_rows": report["download_manifest_rows"],
        **_financial_document_fetch_plan_safety_flags(),
    }


def _financial_document_fetch_blockers_report(report: dict[str, Any]) -> dict[str, Any]:
    return {
        "status": report["status"],
        "mode": "financial-document-fetch-blockers-preview",
        "fetch_blocker_row_count": report["fetch_blocker_row_count"],
        "fetch_blocker_counts": report["fetch_blocker_counts"],
        "fetch_blocker_rows": report["fetch_blocker_rows"],
        **_financial_document_fetch_plan_safety_flags(),
    }


def _financial_document_fetch_plan_safety_flags() -> dict[str, Any]:
    return {
        "documents_downloaded": False,
        "documents_parsed": False,
        "would_fetch_documents": False,
        "would_create_download_directories": False,
        "would_write_raw_documents": False,
        "would_parse_documents": False,
        "would_extract_values": False,
        "would_import_report": False,
        "would_mutate_database": False,
        "files_deleted": False,
        **SAFETY_FLAGS,
    }


def run_operator_exact_document_refill_workspace_v2(args: argparse.Namespace) -> dict[str, Any]:
    fetch_plan_path = _operator_exact_document_refill_fetch_plan_path(args)
    if fetch_plan_path is None or not fetch_plan_path.is_file():
        return _failed_operator_exact_document_refill_workspace(
            [{"message": "operator_exact_document_refill_fetch_plan_input_required"}],
        )
    try:
        fetch_report = _load_json_object(fetch_plan_path)
    except (OSError, ValueError, json.JSONDecodeError):
        return _failed_operator_exact_document_refill_workspace(
            [{"message": "operator_exact_document_refill_fetch_plan_input_invalid", "path": str(fetch_plan_path)}],
        )
    fetch_rows = fetch_report.get("fetch_plan_rows")
    if fetch_report.get("mode") != "financial-document-fetch-plan-preview" or not isinstance(fetch_rows, list) or not all(
        isinstance(row, dict) for row in fetch_rows
    ):
        return _failed_operator_exact_document_refill_workspace(
            [{"message": "operator_exact_document_refill_fetch_plan_input_invalid", "path": str(fetch_plan_path)}],
        )

    warnings: list[dict[str, Any]] = []
    optional_paths = _operator_exact_document_refill_optional_paths(args)
    optional_rows = {
        "fetch_blockers": _load_operator_exact_document_refill_optional_rows(
            optional_paths["fetch_blockers"],
            role="fetch_blockers",
            row_keys=("fetch_blocker_rows", "rows"),
            warnings=warnings,
        ),
        "download_manifest": _load_operator_exact_document_refill_optional_rows(
            optional_paths["download_manifest"],
            role="download_manifest",
            row_keys=("download_manifest_rows", "rows"),
            warnings=warnings,
        ),
        "review_board": _load_operator_exact_document_refill_optional_rows(
            optional_paths["review_board"],
            role="review_board",
            row_keys=("rows",),
            warnings=warnings,
        ),
        "source_trust_workspace": _load_operator_exact_document_refill_optional_rows(
            optional_paths["source_trust_workspace"],
            role="source_trust_workspace",
            row_keys=("rows",),
            warnings=warnings,
        ),
        "source_trust_validation": _load_operator_exact_document_refill_optional_rows(
            optional_paths["source_trust_validation"],
            role="source_trust_validation",
            row_keys=("rows",),
            warnings=warnings,
        ),
        "source_pack_draft": _load_operator_exact_document_refill_optional_rows(
            optional_paths["source_pack_draft"],
            role="source_pack_draft",
            row_keys=("resolutions", "rows"),
            warnings=warnings,
            allow_raw_list=True,
        ),
    }
    artifacts = _operator_exact_document_refill_artifacts(args, fetch_plan_path)
    errors = _operator_exact_document_refill_output_errors(
        args,
        fetch_plan_path=fetch_plan_path,
        optional_paths=optional_paths,
        artifacts=artifacts,
    )
    indexes = {
        role: _operator_exact_document_refill_context_index(rows)
        for role, rows in optional_rows.items()
    }
    rows = [
        _build_operator_exact_document_refill_workspace_row(
            args,
            fetch_row=fetch_row,
            fetch_report=fetch_report,
            indexes=indexes,
            warnings=warnings,
        )
        for fetch_row in fetch_rows
    ]
    template_rows = [_operator_exact_document_refill_template_row(row) for row in rows]
    report = _build_operator_exact_document_refill_workspace_report(
        args,
        fetch_plan_path=fetch_plan_path,
        optional_paths=optional_paths,
        artifacts=artifacts,
        rows=rows,
        warnings=warnings,
        errors=errors,
    )
    if not errors:
        try:
            write_json_report(report, artifacts["workspace_json"])
            _write_flat_csv(rows, OPERATOR_EXACT_DOCUMENT_REFILL_WORKSPACE_FIELDS, artifacts["workspace_csv"])
            write_operator_exact_document_refill_workspace_markdown(report, artifacts["workspace_markdown"])
            write_json_report(
                {
                    "status": report["status"],
                    "mode": "operator-exact-document-refill-template-v2",
                    "row_count": len(template_rows),
                    "template_rows": template_rows,
                    **_operator_exact_document_refill_safety_flags(),
                },
                artifacts["template_json"],
            )
            _write_flat_csv(template_rows, OPERATOR_EXACT_DOCUMENT_REFILL_TEMPLATE_FIELDS, artifacts["template_csv"])
            write_operator_exact_document_refill_rerun_markdown(report, artifacts["rerun_markdown"])
        except OSError as exc:
            report["status"] = "failed"
            report["errors"] = [*report["errors"], {"message": str(exc)}]
    return report


def _operator_exact_document_refill_fetch_plan_path(args: argparse.Namespace) -> Path | None:
    if args.financial_document_fetch_plan_input is not None:
        return args.financial_document_fetch_plan_input
    if args.operator_resolution_chain_output_dir is not None:
        return args.operator_resolution_chain_output_dir / FINANCIAL_DOCUMENT_FETCH_PLAN_ARTIFACT_NAMES["fetch_plan_json"]
    return None


def _operator_exact_document_refill_optional_paths(args: argparse.Namespace) -> dict[str, Path | None]:
    output_dir = args.operator_resolution_chain_output_dir
    defaults = {
        "fetch_blockers": FINANCIAL_DOCUMENT_FETCH_PLAN_ARTIFACT_NAMES["fetch_blockers_json"],
        "download_manifest": FINANCIAL_DOCUMENT_FETCH_PLAN_ARTIFACT_NAMES["download_manifest_json"],
        "review_board": OPERATOR_RESOLUTION_CHAIN_REVIEW_BOARD_ARTIFACT_NAMES["board_json"],
        "source_trust_workspace": OPERATOR_RESOLUTION_SOURCE_TRUST_ARTIFACT_NAMES["workspace_json"],
        "source_trust_validation": OPERATOR_RESOLUTION_SOURCE_TRUST_REFILL_ARTIFACT_NAMES["validation_json"],
        "source_pack_draft": OPERATOR_RESOLUTION_SOURCE_TRUST_REFILL_ARTIFACT_NAMES["source_pack_draft_json"],
    }
    overrides = {
        "fetch_blockers": args.financial_document_fetch_blockers_input,
        "download_manifest": args.financial_document_download_manifest_input,
        "review_board": args.operator_resolution_chain_review_board_input,
        "source_trust_workspace": args.operator_resolution_source_trust_workspace_input,
        "source_trust_validation": args.operator_resolution_source_trust_validation_input,
        "source_pack_draft": args.operator_resolution_source_pack_draft_input,
    }
    return {
        role: overrides[role] or (output_dir / filename if output_dir is not None else None)
        for role, filename in defaults.items()
    }


def _load_operator_exact_document_refill_optional_rows(
    path: Path | None,
    *,
    role: str,
    row_keys: Sequence[str],
    warnings: list[dict[str, Any]],
    allow_raw_list: bool = False,
) -> list[dict[str, Any]]:
    if path is None or not path.is_file():
        warnings.append({"message": f"operator_exact_document_refill_optional_artifact_missing:{role}"})
        return []
    try:
        with path.open("r", encoding="utf-8-sig") as handle:
            payload = json.load(handle)
        rows: Any = payload if allow_raw_list and isinstance(payload, list) else None
        if isinstance(payload, dict):
            for key in row_keys:
                if payload.get(key) is not None:
                    rows = payload.get(key)
                    break
        if not isinstance(rows, list) or not all(isinstance(row, dict) for row in rows):
            raise ValueError("optional artifact rows are malformed")
        return rows
    except (OSError, ValueError, json.JSONDecodeError):
        warnings.append({"message": f"operator_exact_document_refill_optional_artifact_unreadable:{role}", "path": str(path)})
        return []


def _operator_exact_document_refill_artifacts(args: argparse.Namespace, fetch_plan_path: Path) -> dict[str, Path]:
    output_dir = args.operator_resolution_chain_output_dir or fetch_plan_path.parent
    overrides = {
        "workspace_json": args.operator_exact_document_refill_workspace_output,
        "workspace_csv": args.operator_exact_document_refill_workspace_csv_output,
        "workspace_markdown": args.operator_exact_document_refill_workspace_markdown_output,
        "template_json": args.operator_exact_document_refill_template_output,
        "template_csv": args.operator_exact_document_refill_template_csv_output,
        "rerun_markdown": args.operator_exact_document_refill_rerun_markdown_output,
    }
    return {
        role: overrides[role] or output_dir / filename
        for role, filename in OPERATOR_EXACT_DOCUMENT_REFILL_ARTIFACT_NAMES.items()
    }


def _operator_exact_document_refill_output_errors(
    args: argparse.Namespace,
    *,
    fetch_plan_path: Path,
    optional_paths: dict[str, Path | None],
    artifacts: dict[str, Path],
) -> list[dict[str, Any]]:
    inputs = [fetch_plan_path, *(path for path in optional_paths.values() if path is not None)]
    outputs = [*artifacts.values(), *(path for path in (args.json_output, args.markdown_output) if path is not None)]
    for index, output in enumerate(outputs):
        if any(_paths_equal(output, other) for other in outputs[index + 1 :]):
            return [{"message": "operator_exact_document_refill_output_must_not_equal_input"}]
        if any(_paths_equal(output, input_path) for input_path in inputs):
            return [{"message": "operator_exact_document_refill_output_must_not_equal_input"}]
    return []


def _operator_exact_document_refill_context_index(rows: list[dict[str, Any]]) -> dict[str, list[dict[str, Any]]]:
    index: dict[str, list[dict[str, Any]]] = {}
    for row in rows:
        for key in _operator_exact_document_refill_join_keys(row):
            index.setdefault(key, []).append(row)
    return index


def _operator_exact_document_refill_join_keys(row: dict[str, Any]) -> list[str]:
    keys: list[str] = []
    resolution_id = str(row.get("resolution_id") or "")
    if resolution_id:
        keys.append(f"resolution:{resolution_id}")
    company_id = str(row.get("canonical_company_id") or row.get("company_id") or "")
    if company_id:
        keys.append(f"company:{company_id}")
    fetch_plan_id = str(row.get("fetch_plan_id") or "")
    if fetch_plan_id:
        keys.append(f"fetch:{fetch_plan_id}")
    return keys


def _operator_exact_document_refill_match_context(
    fetch_row: dict[str, Any],
    *,
    role: str,
    index: dict[str, list[dict[str, Any]]],
    warnings: list[dict[str, Any]],
) -> tuple[dict[str, Any], bool]:
    preferred_keys = _operator_exact_document_refill_join_keys(fetch_row)
    for prefix in ("fetch:", "resolution:", "company:"):
        matches: list[dict[str, Any]] = []
        for key in preferred_keys:
            if key.startswith(prefix):
                matches = index.get(key) or []
                break
        unique = _operator_exact_document_refill_unique_rows(matches)
        if len(unique) == 1:
            return unique[0], False
        if len(unique) > 1:
            if role == "fetch_blockers":
                return {
                    "blocker_codes": [
                        str(row.get("blocker_code") or "")
                        for row in unique
                        if row.get("blocker_code")
                    ]
                }, False
            warnings.append({"message": f"operator_exact_document_refill_ambiguous_context:{role}"})
            return {}, True
    return {}, False


def _operator_exact_document_refill_unique_rows(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    unique: list[dict[str, Any]] = []
    for row in rows:
        if not any(existing is row for existing in unique):
            unique.append(row)
    return unique


def _build_operator_exact_document_refill_workspace_row(
    args: argparse.Namespace,
    *,
    fetch_row: dict[str, Any],
    fetch_report: dict[str, Any],
    indexes: dict[str, dict[str, list[dict[str, Any]]]],
    warnings: list[dict[str, Any]],
) -> dict[str, Any]:
    contexts: dict[str, dict[str, Any]] = {}
    ambiguous = False
    for role, index in indexes.items():
        contexts[role], role_ambiguous = _operator_exact_document_refill_match_context(
            fetch_row,
            role=role,
            index=index,
            warnings=warnings,
        )
        ambiguous = ambiguous or role_ambiguous
    trust = _operator_exact_document_refill_baseline_context(contexts)
    board = contexts["review_board"]
    blockers = contexts["fetch_blockers"]
    manifest = contexts["download_manifest"]
    historical_url = str(
        fetch_row.get("historical_fallback_url")
        or trust.get("latest_historical_document_url")
        or board.get("latest_historical_document_url")
        or ""
    )
    manual_exact_url = str(board.get("operator_fill_exact_document_url") or "")
    manual_preserved = bool(
        manual_exact_url
        or board.get("operator_fill_document_title")
        or board.get("operator_fill_document_date")
        or board.get("operator_fill_notes")
    )
    status = _operator_exact_document_refill_workspace_status(
        fetch_row,
        fetch_report=fetch_report,
        trust=trust,
        ambiguous=ambiguous,
        historical_url=historical_url,
        manual_exact_url=manual_exact_url,
    )
    action = _operator_exact_document_refill_workspace_action(status)
    reasons = _operator_exact_document_refill_workspace_reasons(
        args,
        fetch_row=fetch_row,
        trust=trust,
        status=status,
        historical_url=historical_url,
        manual_preserved=manual_preserved,
    )
    guidance = _operator_exact_document_refill_guidance(
        status,
        trusted_hosts=trust["trusted_source_hosts"],
    )
    target_period = fetch_row.get("target_reporting_period") or args.operator_exact_document_refill_target_period
    required_type = fetch_row.get("required_report_type") or args.operator_exact_document_refill_required_report_type
    required_standard = fetch_row.get("required_standard") or args.operator_exact_document_refill_required_standard
    required_consolidated = _as_bool(
        fetch_row.get("required_consolidated")
        if fetch_row.get("required_consolidated") is not None
        else args.operator_exact_document_refill_required_consolidated
    )
    company_id = fetch_row.get("company_id") or ""
    company_name = fetch_row.get("company_name") or ""
    trusted_hosts = trust["trusted_source_hosts"]
    planned_raw_path = fetch_row.get("planned_raw_document_path") or manifest.get("planned_raw_document_path") or ""
    planned_hash_path = fetch_row.get("planned_hash_manifest_path") or manifest.get("planned_hash_manifest_path") or ""
    return {
        "workspace_id": f"operator_exact_document_refill:{fetch_row.get('fetch_plan_id') or company_id}",
        "resolution_id": fetch_row.get("resolution_id") or board.get("resolution_id") or "",
        "company_id": company_id,
        "company_name": company_name,
        "canonical_company_id": fetch_row.get("canonical_company_id") or company_id,
        "canonical_company_name": fetch_row.get("canonical_company_name") or company_name,
        "target_reporting_period": target_period,
        "required_report_type": required_type,
        "required_standard": required_standard,
        "required_consolidated": required_consolidated,
        "fetch_plan_status": fetch_row.get("fetch_plan_status") or "",
        "fetch_plan_reason_codes": list(fetch_row.get("fetch_plan_reason_codes") or []),
        "fetch_plan_warnings": list(fetch_row.get("fetch_plan_warnings") or []),
        "download_attempt_allowed_now": bool(fetch_row.get("download_attempt_allowed_now")),
        "planned_raw_document_path": planned_raw_path,
        "planned_hash_manifest_path": planned_hash_path,
        "source_trust_status": trust["source_trust_status"],
        "trusted_source_hosts": trusted_hosts,
        "source_context_status": trust["source_context_status"],
        "source_context_next_action": trust["source_context_next_action"],
        "source_context_blocker_codes": trust["source_context_blocker_codes"],
        "current_known_source_page_url": trust["current_known_source_page_url"],
        "current_known_document_url": trust["current_known_document_url"],
        "latest_historical_document_url": historical_url,
        "historical_fallback_allowed_as_target_evidence": False,
        "historical_fallback_allowed_as_trusted_source": False,
        "workspace_status": status,
        "workspace_priority": "high" if status != "diagnostic_only" else "low",
        "workspace_action": action,
        "workspace_reason_codes": reasons,
        "workspace_errors": [],
        "workspace_warnings": ["manual_url_requires_future_validation"] if manual_preserved else [],
        **guidance,
        "READONLY_company_id": company_id,
        "READONLY_company_name": company_name,
        "READONLY_target_reporting_period": target_period,
        "READONLY_required_report_type": required_type,
        "READONLY_required_standard": required_standard,
        "READONLY_required_consolidated": required_consolidated,
        "READONLY_fetch_plan_status": fetch_row.get("fetch_plan_status") or "",
        "READONLY_source_trust_status": trust["source_trust_status"],
        "READONLY_trusted_source_hosts": trusted_hosts,
        "READONLY_current_known_source_page_url": trust["current_known_source_page_url"],
        "READONLY_latest_historical_document_url": historical_url,
        "READONLY_planned_raw_document_path": planned_raw_path,
        "READONLY_planned_hash_manifest_path": planned_hash_path,
        "operator_fill_exact_document_url": manual_exact_url,
        "operator_fill_document_title": board.get("operator_fill_document_title") or "",
        "operator_fill_document_publication_date": board.get("operator_fill_document_publication_date")
        or board.get("operator_fill_document_date")
        or "",
        "operator_fill_document_report_type": board.get("operator_fill_document_report_type")
        or board.get("operator_fill_report_type")
        or required_type,
        "operator_fill_document_accounting_standard": board.get("operator_fill_document_accounting_standard")
        or board.get("operator_fill_accounting_standard")
        or required_standard,
        "operator_fill_document_consolidated": board.get("operator_fill_document_consolidated")
        if board.get("operator_fill_document_consolidated") is not None
        else required_consolidated,
        "operator_fill_document_language": board.get("operator_fill_document_language") or "",
        "operator_fill_notes": board.get("operator_fill_notes") or "",
        **_operator_exact_document_refill_row_safety_flags(),
    }


def _operator_exact_document_refill_baseline_context(contexts: dict[str, dict[str, Any]]) -> dict[str, Any]:
    workspace = contexts["source_trust_workspace"]
    validation = contexts["source_trust_validation"]
    draft = contexts["source_pack_draft"]
    board = contexts["review_board"]
    if workspace:
        hosts = _financial_document_fetch_list(workspace.get("trusted_source_hosts"))
        return _operator_exact_document_refill_baseline_result(
            status=str(workspace.get("source_trust_status") or ""),
            hosts=hosts,
            page_url=str(workspace.get("current_known_source_page_url") or ""),
            document_url=str(workspace.get("current_known_document_url") or ""),
            historical_url=str(workspace.get("latest_historical_document_url") or ""),
            next_action=str(workspace.get("next_required_action") or ""),
            blockers=_financial_document_fetch_list(workspace.get("trusted_source_status_reason_codes")),
        )
    if validation:
        hosts = _financial_document_fetch_list(validation.get("baseline_trusted_source_hosts"))
        return _operator_exact_document_refill_baseline_result(
            status="ready_for_document_url_refill" if hosts else "trusted_source_missing",
            hosts=hosts,
            page_url=str(validation.get("baseline_current_known_source_page_url") or ""),
            document_url=str(validation.get("baseline_current_known_document_url") or ""),
            historical_url=str(validation.get("latest_historical_document_url") or ""),
            next_action=str(validation.get("operator_next_step") or ""),
            blockers=_financial_document_fetch_list(validation.get("validation_reason_codes")),
        )
    if draft:
        page_url = str(draft.get("current_known_source_page_url") or "")
        document_url = str(draft.get("current_known_document_url") or "")
        hosts = sorted({_host(url) for url in (page_url, document_url) if _financial_document_fetch_url_is_http(url)})
        return _operator_exact_document_refill_baseline_result(
            status="ready_for_document_url_refill" if hosts else "trusted_source_missing",
            hosts=hosts,
            page_url=page_url,
            document_url=document_url,
            historical_url=str(draft.get("latest_historical_document_url") or ""),
            next_action="",
            blockers=[],
        )
    if board:
        hosts = _financial_document_fetch_list(board.get("trusted_source_hosts"))
        return _operator_exact_document_refill_baseline_result(
            status="ready_for_document_url_refill" if hosts else "trusted_source_missing",
            hosts=hosts,
            page_url="",
            document_url="",
            historical_url=str(board.get("latest_historical_document_url") or ""),
            next_action=str(board.get("next_required_action") or ""),
            blockers=[],
        )
    return _operator_exact_document_refill_baseline_result(
        status="",
        hosts=[],
        page_url="",
        document_url="",
        historical_url="",
        next_action="",
        blockers=[],
    )


def _operator_exact_document_refill_baseline_result(
    *,
    status: str,
    hosts: list[str],
    page_url: str,
    document_url: str,
    historical_url: str,
    next_action: str,
    blockers: list[str],
) -> dict[str, Any]:
    return {
        "source_trust_status": status,
        "trusted_source_hosts": sorted(set(hosts)),
        "current_known_source_page_url": page_url,
        "current_known_document_url": document_url,
        "latest_historical_document_url": historical_url,
        "source_context_status": status,
        "source_context_next_action": next_action,
        "source_context_blocker_codes": blockers,
        "context_available": bool(status or hosts or page_url or document_url or historical_url),
    }


def _operator_exact_document_refill_workspace_status(
    fetch_row: dict[str, Any],
    *,
    fetch_report: dict[str, Any],
    trust: dict[str, Any],
    ambiguous: bool,
    historical_url: str,
    manual_exact_url: str,
) -> str:
    fetch_status = str(fetch_row.get("fetch_plan_status") or "")
    if fetch_status == "blocked_disk_guard" or fetch_report.get("disk_guard_status") == "blocked":
        return "blocked_disk_guard"
    historical_only = bool(
        fetch_status == "blocked_historical_fallback_only"
        or (historical_url and manual_exact_url == historical_url)
        or (historical_url and not trust["trusted_source_hosts"] and not trust["current_known_source_page_url"])
    )
    if historical_only:
        return "blocked_historical_fallback_only"
    if fetch_status != "blocked_missing_exact_document_url":
        return "blocked_fetch_plan_not_missing_exact_url"
    if ambiguous:
        return "blocked_unknown_readiness"
    if trust["source_trust_status"] in {"trusted_source_missing", "trusted_source_conflict", "trusted_source_needs_review"}:
        return "blocked_source_trust_required_before_exact_document_refill"
    if trust["trusted_source_hosts"]:
        return "ready_for_exact_document_url_refill"
    if not trust["context_available"]:
        return "blocked_unknown_readiness"
    return "blocked_source_trust_required_before_exact_document_refill"


def _operator_exact_document_refill_workspace_action(status: str) -> str:
    return {
        "ready_for_exact_document_url_refill": "fill_exact_target_annual_ifrs_document_url",
        "blocked_source_trust_required_before_exact_document_refill": "fill_official_baseline_source_page_first",
        "blocked_historical_fallback_only": "do_not_copy_historical_fallback",
        "blocked_disk_guard": "review_fetch_plan_blocker_first",
        "blocked_fetch_plan_not_missing_exact_url": "review_fetch_plan_blocker_first",
        "blocked_unknown_readiness": "review_fetch_plan_blocker_first",
        "diagnostic_only": "noop",
    }.get(status, "noop")


def _operator_exact_document_refill_workspace_reasons(
    args: argparse.Namespace,
    *,
    fetch_row: dict[str, Any],
    trust: dict[str, Any],
    status: str,
    historical_url: str,
    manual_preserved: bool,
) -> list[str]:
    reasons = list(fetch_row.get("fetch_plan_reason_codes") or [])
    _append_unique(reasons, f"target_period_required_{args.operator_exact_document_refill_target_period}")
    _append_unique(reasons, "annual_report_required")
    _append_unique(reasons, "ifrs_required")
    if args.operator_exact_document_refill_required_consolidated:
        _append_unique(reasons, "consolidated_required")
    if status == "blocked_disk_guard":
        _append_unique(reasons, "disk_guard_blocked")
    else:
        _append_unique(reasons, "disk_guard_passed")
    if trust["trusted_source_hosts"]:
        _append_unique(reasons, "trusted_source_available")
    if trust["source_trust_status"] in {"trusted_source_missing", "trusted_source_conflict", "trusted_source_needs_review"}:
        _append_unique(reasons, "source_trust_missing")
        _append_unique(reasons, "source_context_required_before_document_refill")
    if historical_url:
        _append_unique(reasons, "historical_fallback_diagnostic_only")
    if manual_preserved:
        _append_unique(reasons, "manual_url_requires_future_validation")
    return reasons


def _operator_exact_document_refill_guidance(status: str, *, trusted_hosts: list[str]) -> dict[str, str]:
    hosts = ", ".join(trusted_hosts) if trusted_hosts else "baseline trusted hosts unavailable"
    safe_source_hint = (
        "Use only an official issuer reporting, investor-relations, or official disclosure page. "
        "Manual source URLs require a separate controlled source-trust validation."
    )
    safe_document_hint = (
        f"Fill only an exact official target-period annual IFRS document URL from baseline hosts: {hosts}. "
        "The URL remains a future-validation candidate."
    )
    forbidden = "Do not copy historical fallback URLs, generic landing pages, interim reports, RAS reports, or prospectuses."
    if status == "ready_for_exact_document_url_refill":
        instruction = "Fill the exact official target-period annual IFRS document URL. It will require future strict validation."
    elif status == "blocked_source_trust_required_before_exact_document_refill":
        instruction = "Fill or review official baseline source context first through the Task126/127 source-trust workflow."
    elif status == "blocked_historical_fallback_only":
        instruction = "Do not copy the historical fallback URL. Find current baseline source context or the exact target-period report."
    else:
        instruction = "Review the fetch-plan blocker before filling an exact document URL."
    return {
        "operator_instruction": instruction,
        "safe_source_hint": safe_source_hint,
        "safe_document_hint": safe_document_hint,
        "forbidden_url_hint": forbidden,
        "rerun_after_fill_hint": "After editing the Task134 template, run the future operator-exact-document-refill-validate-v2 mode.",
    }


def _operator_exact_document_refill_template_row(row: dict[str, Any]) -> dict[str, Any]:
    template = {field: row.get(field, "") for field in OPERATOR_EXACT_DOCUMENT_REFILL_TEMPLATE_FIELDS}
    template["READONLY_forbidden_url_hint"] = row.get("forbidden_url_hint") or ""
    return template


def _build_operator_exact_document_refill_workspace_report(
    args: argparse.Namespace,
    *,
    fetch_plan_path: Path,
    optional_paths: dict[str, Path | None],
    artifacts: dict[str, Path],
    rows: list[dict[str, Any]],
    warnings: list[dict[str, Any]],
    errors: list[dict[str, Any]],
) -> dict[str, Any]:
    ready_count = sum(1 for row in rows if row.get("workspace_status") == "ready_for_exact_document_url_refill")
    status = "failed" if errors else "passed" if rows and ready_count == len(rows) and not warnings else "warning"
    return {
        "status": status,
        "mode": "operator-exact-document-refill-workspace-v2",
        "financial_document_fetch_plan_input": str(fetch_plan_path),
        "optional_inputs": {role: _path_value(path) for role, path in optional_paths.items()},
        "target_reporting_period": str(args.operator_exact_document_refill_target_period),
        "required_report_type": str(args.operator_exact_document_refill_required_report_type),
        "required_standard": str(args.operator_exact_document_refill_required_standard),
        "required_consolidated": args.operator_exact_document_refill_required_consolidated,
        "row_count": len(rows),
        "ready_for_exact_document_url_refill_count": ready_count,
        "blocked_source_trust_count": sum(
            1 for row in rows if row.get("workspace_status") == "blocked_source_trust_required_before_exact_document_refill"
        ),
        "blocked_historical_fallback_count": sum(
            1 for row in rows if row.get("workspace_status") == "blocked_historical_fallback_only"
        ),
        "blocked_disk_guard_count": sum(1 for row in rows if row.get("workspace_status") == "blocked_disk_guard"),
        "blocked_unknown_readiness_count": sum(
            1 for row in rows if row.get("workspace_status") == "blocked_unknown_readiness"
        ),
        "diagnostic_only_count": sum(1 for row in rows if row.get("workspace_status") == "diagnostic_only"),
        "workspace_status_counts": _count_by_key(rows, "workspace_status"),
        "workspace_action_counts": _count_by_key(rows, "workspace_action"),
        "rows": rows,
        "artifacts": {role: str(path) for role, path in artifacts.items()},
        "warnings": warnings,
        "errors": errors,
        "next_steps": _next_steps("operator-exact-document-refill-workspace-v2", status),
        **_operator_exact_document_refill_safety_flags(),
    }


def _failed_operator_exact_document_refill_workspace(errors: list[dict[str, Any]]) -> dict[str, Any]:
    return {
        "status": "failed",
        "mode": "operator-exact-document-refill-workspace-v2",
        "row_count": 0,
        "ready_for_exact_document_url_refill_count": 0,
        "blocked_source_trust_count": 0,
        "blocked_historical_fallback_count": 0,
        "blocked_disk_guard_count": 0,
        "blocked_unknown_readiness_count": 0,
        "diagnostic_only_count": 0,
        "workspace_status_counts": {},
        "workspace_action_counts": {},
        "rows": [],
        "warnings": [],
        "errors": errors,
        **_operator_exact_document_refill_safety_flags(),
    }


def _operator_exact_document_refill_row_safety_flags() -> dict[str, Any]:
    return {
        "would_fetch_document": False,
        "would_download_document": False,
        "would_parse_document": False,
        "would_extract_values": False,
        "would_import_report": False,
        "would_mutate_database": False,
        "would_mutate_scores": False,
        "would_trigger_paper_trading": False,
        "would_delete_files": False,
    }


def _operator_exact_document_refill_safety_flags() -> dict[str, Any]:
    return {
        "documents_downloaded": False,
        "documents_parsed": False,
        "files_deleted": False,
        "would_fetch_documents": False,
        "would_download_documents": False,
        "would_parse_documents": False,
        "would_extract_values": False,
        "would_import_report": False,
        "would_mutate_database": False,
        **SAFETY_FLAGS,
    }


def run_operator_exact_document_refill_validate_v2(args: argparse.Namespace) -> dict[str, Any]:
    refill_path = _operator_exact_document_refill_validation_input_path(args)
    if refill_path is None or not refill_path.is_file():
        return _failed_operator_exact_document_refill_validation(
            [{"message": "operator_exact_document_refill_input_required"}],
        )
    try:
        refill_rows = _load_operator_exact_document_refill_template_csv(refill_path)
    except (OSError, ValueError, csv.Error):
        return _failed_operator_exact_document_refill_validation(
            [{"message": "operator_exact_document_refill_input_invalid", "path": str(refill_path)}],
        )

    warnings: list[dict[str, Any]] = []
    workspace_path = _operator_exact_document_refill_validation_workspace_path(args)
    workspace_rows = _load_operator_exact_document_refill_validation_optional_rows(
        workspace_path,
        role="workspace",
        row_keys=("rows",),
        warnings=warnings,
        missing_warning="operator_exact_document_refill_workspace_missing_validation_conservative",
    )
    fetch_plan_path = _operator_exact_document_refill_validation_fetch_plan_path(args)
    fetch_rows = _load_operator_exact_document_refill_validation_optional_rows(
        fetch_plan_path,
        role="fetch_plan",
        row_keys=("fetch_plan_rows",),
        warnings=warnings,
    )
    artifacts = _operator_exact_document_refill_validation_artifacts(args)
    errors = _operator_exact_document_refill_validation_output_errors(
        args,
        inputs=[refill_path, workspace_path, fetch_plan_path],
        artifacts=artifacts,
    )
    workspace_index = _operator_exact_document_refill_validation_context_index(workspace_rows)
    fetch_index = _operator_exact_document_refill_validation_context_index(fetch_rows)
    contexts = [
        _operator_exact_document_refill_validation_context(
            refill_row,
            workspace_index=workspace_index,
            fetch_index=fetch_index,
        )
        for refill_row in refill_rows
    ]
    duplicate_identity_keys, duplicate_urls = _operator_exact_document_refill_validation_duplicates(refill_rows)
    validation_rows = [
        _build_operator_exact_document_refill_validation_row(
            args,
            refill_row=refill_row,
            context=context,
            workspace_available=bool(workspace_rows),
            duplicate_identity_keys=duplicate_identity_keys,
            duplicate_urls=duplicate_urls,
        )
        for refill_row, context in zip(refill_rows, contexts)
    ]
    accepted_rows = [
        _operator_exact_document_refill_accepted_candidate_row(row)
        for row in validation_rows
        if row.get("validation_status") == "valid_future_exact_document_candidate"
    ]
    blocker_rows = [
        _operator_exact_document_refill_blocker_row(row)
        for row in validation_rows
        if row.get("validation_status") != "valid_future_exact_document_candidate"
    ]
    report = _build_operator_exact_document_refill_validation_report(
        args,
        refill_path=refill_path,
        workspace_path=workspace_path,
        fetch_plan_path=fetch_plan_path,
        artifacts=artifacts,
        validation_rows=validation_rows,
        accepted_rows=accepted_rows,
        blocker_rows=blocker_rows,
        warnings=warnings,
        errors=errors,
    )
    if not errors:
        try:
            _write_optional_json_report(report, artifacts["validation_json"])
            _write_optional_flat_csv(validation_rows, OPERATOR_EXACT_DOCUMENT_REFILL_VALIDATION_FIELDS, artifacts["validation_csv"])
            if artifacts["validation_markdown"] is not None:
                write_operator_exact_document_refill_validation_markdown(report, artifacts["validation_markdown"])
            _write_optional_json_report(
                {
                    "status": report["status"],
                    "mode": "operator-exact-document-refill-accepted-candidates-v2",
                    "row_count": len(accepted_rows),
                    "accepted_candidate_rows": accepted_rows,
                    **_operator_exact_document_refill_validation_safety_flags(),
                },
                artifacts["accepted_candidates_json"],
            )
            _write_optional_flat_csv(
                accepted_rows,
                OPERATOR_EXACT_DOCUMENT_REFILL_ACCEPTED_CANDIDATE_FIELDS,
                artifacts["accepted_candidates_csv"],
            )
            _write_optional_json_report(
                {
                    "status": report["status"],
                    "mode": "operator-exact-document-refill-blockers-v2",
                    "row_count": len(blocker_rows),
                    "blocker_rows": blocker_rows,
                    **_operator_exact_document_refill_validation_safety_flags(),
                },
                artifacts["blockers_json"],
            )
            _write_optional_flat_csv(
                blocker_rows,
                OPERATOR_EXACT_DOCUMENT_REFILL_BLOCKER_FIELDS,
                artifacts["blockers_csv"],
            )
        except OSError as exc:
            report["status"] = "failed"
            report["errors"] = [*report["errors"], {"message": str(exc)}]
    return report


def _operator_exact_document_refill_validation_input_path(args: argparse.Namespace) -> Path | None:
    if args.operator_exact_document_refill_input is not None:
        return args.operator_exact_document_refill_input
    if args.operator_resolution_chain_output_dir is not None:
        return args.operator_resolution_chain_output_dir / OPERATOR_EXACT_DOCUMENT_REFILL_ARTIFACT_NAMES["template_csv"]
    return None


def _operator_exact_document_refill_validation_workspace_path(args: argparse.Namespace) -> Path | None:
    if args.operator_exact_document_refill_workspace_input is not None:
        return args.operator_exact_document_refill_workspace_input
    if args.operator_resolution_chain_output_dir is not None:
        return args.operator_resolution_chain_output_dir / OPERATOR_EXACT_DOCUMENT_REFILL_ARTIFACT_NAMES["workspace_json"]
    return None


def _operator_exact_document_refill_validation_fetch_plan_path(args: argparse.Namespace) -> Path | None:
    if args.financial_document_fetch_plan_input is not None:
        return args.financial_document_fetch_plan_input
    if args.operator_resolution_chain_output_dir is not None:
        return args.operator_resolution_chain_output_dir / FINANCIAL_DOCUMENT_FETCH_PLAN_ARTIFACT_NAMES["fetch_plan_json"]
    return None


def _load_operator_exact_document_refill_template_csv(path: Path) -> list[dict[str, Any]]:
    with path.open("r", encoding="utf-8-sig", newline="") as handle:
        reader = csv.DictReader(handle)
        required = {"workspace_id", "company_id", "operator_fill_exact_document_url"}
        if reader.fieldnames is None or not required.issubset(set(reader.fieldnames)):
            raise ValueError("operator exact document refill template columns are malformed")
        return [
            {key: _normalize_cell(value) for key, value in raw.items() if key}
            for raw in reader
        ]


def _load_operator_exact_document_refill_validation_optional_rows(
    path: Path | None,
    *,
    role: str,
    row_keys: Sequence[str],
    warnings: list[dict[str, Any]],
    missing_warning: str | None = None,
) -> list[dict[str, Any]]:
    if path is None or not path.is_file():
        warnings.append({"message": missing_warning or f"operator_exact_document_refill_optional_artifact_missing:{role}"})
        return []
    try:
        payload = _load_json_object(path)
        for key in row_keys:
            rows = payload.get(key)
            if isinstance(rows, list) and all(isinstance(row, dict) for row in rows):
                return rows
        raise ValueError("optional artifact rows are malformed")
    except (OSError, ValueError, json.JSONDecodeError):
        warnings.append(
            {
                "message": missing_warning or f"operator_exact_document_refill_optional_artifact_unreadable:{role}",
                "path": str(path),
            }
        )
        return []


def _operator_exact_document_refill_validation_artifacts(args: argparse.Namespace) -> dict[str, Path | None]:
    output_dir = args.operator_resolution_chain_output_dir
    overrides = {
        "validation_json": args.operator_exact_document_refill_validation_output,
        "validation_csv": args.operator_exact_document_refill_validation_csv_output,
        "validation_markdown": args.operator_exact_document_refill_validation_markdown_output,
        "accepted_candidates_json": args.operator_exact_document_refill_accepted_candidates_output,
        "accepted_candidates_csv": args.operator_exact_document_refill_accepted_candidates_csv_output,
        "blockers_json": args.operator_exact_document_refill_blockers_output,
        "blockers_csv": args.operator_exact_document_refill_blockers_csv_output,
    }
    return {
        role: overrides[role] or (output_dir / filename if output_dir is not None else None)
        for role, filename in OPERATOR_EXACT_DOCUMENT_REFILL_VALIDATION_ARTIFACT_NAMES.items()
    }


def _operator_exact_document_refill_validation_output_errors(
    args: argparse.Namespace,
    *,
    inputs: list[Path | None],
    artifacts: dict[str, Path | None],
) -> list[dict[str, Any]]:
    outputs = [
        *(path for path in artifacts.values() if path is not None),
        *(path for path in (args.json_output, args.markdown_output) if path is not None),
    ]
    protected = [path for path in inputs if path is not None]
    for index, output in enumerate(outputs):
        if any(_paths_equal(output, other) for other in outputs[index + 1 :]):
            return [{"message": "operator_exact_document_refill_validation_output_must_not_equal_input"}]
        if any(_paths_equal(output, input_path) for input_path in protected):
            return [{"message": "operator_exact_document_refill_validation_output_must_not_equal_input"}]
    return []


def _operator_exact_document_refill_validation_context_index(rows: list[dict[str, Any]]) -> dict[str, list[dict[str, Any]]]:
    index: dict[str, list[dict[str, Any]]] = {}
    for row in rows:
        for key in _operator_exact_document_refill_validation_join_keys(row):
            index.setdefault(key, []).append(row)
    return index


def _operator_exact_document_refill_validation_join_keys(row: dict[str, Any]) -> list[str]:
    keys: list[str] = []
    for prefix, field in (
        ("workspace", "workspace_id"),
        ("canonical", "canonical_company_id"),
        ("company", "company_id"),
    ):
        value = str(row.get(field) or "")
        if value:
            keys.append(f"{prefix}:{value}")
    return keys


def _operator_exact_document_refill_validation_context(
    refill_row: dict[str, Any],
    *,
    workspace_index: dict[str, list[dict[str, Any]]],
    fetch_index: dict[str, list[dict[str, Any]]],
) -> dict[str, Any]:
    workspace, workspace_ambiguous = _operator_exact_document_refill_validation_match(refill_row, workspace_index)
    fetch, fetch_ambiguous = _operator_exact_document_refill_validation_match(
        {**workspace, **refill_row},
        fetch_index,
    )
    return {
        "workspace": workspace,
        "fetch_plan": fetch,
        "workspace_ambiguous": workspace_ambiguous,
        "fetch_plan_ambiguous": fetch_ambiguous,
    }


def _operator_exact_document_refill_validation_match(
    row: dict[str, Any],
    index: dict[str, list[dict[str, Any]]],
) -> tuple[dict[str, Any], bool]:
    for key in _operator_exact_document_refill_validation_join_keys(row):
        matches = _operator_exact_document_refill_unique_rows(index.get(key) or [])
        if len(matches) == 1:
            return matches[0], False
        if len(matches) > 1:
            return {}, True
    return {}, False


def _operator_exact_document_refill_validation_duplicates(
    refill_rows: list[dict[str, Any]],
) -> tuple[set[str], set[str]]:
    identity_counts: dict[str, int] = {}
    url_companies: dict[str, set[str]] = {}
    for row in refill_rows:
        identity = str(row.get("workspace_id") or row.get("canonical_company_id") or row.get("company_id") or "")
        if identity:
            identity_counts[identity] = identity_counts.get(identity, 0) + 1
        normalized_url = _normalize_candidate_url(str(row.get("operator_fill_exact_document_url") or ""))
        company = str(row.get("canonical_company_id") or row.get("company_id") or identity)
        if normalized_url:
            url_companies.setdefault(normalized_url, set()).add(company)
    return (
        {key for key, count in identity_counts.items() if count > 1},
        {url for url, companies in url_companies.items() if len(companies) > 1},
    )


def _build_operator_exact_document_refill_validation_row(
    args: argparse.Namespace,
    *,
    refill_row: dict[str, Any],
    context: dict[str, Any],
    workspace_available: bool,
    duplicate_identity_keys: set[str],
    duplicate_urls: set[str],
) -> dict[str, Any]:
    workspace = context["workspace"]
    fetch = context["fetch_plan"]
    workspace_id = str(refill_row.get("workspace_id") or workspace.get("workspace_id") or "")
    company_id = str(workspace.get("company_id") or refill_row.get("company_id") or "")
    company_name = str(workspace.get("company_name") or refill_row.get("company_name") or "")
    canonical_company_id = str(workspace.get("canonical_company_id") or company_id)
    canonical_company_name = str(workspace.get("canonical_company_name") or company_name)
    target_period = str(args.operator_exact_document_refill_target_period)
    required_type = str(args.operator_exact_document_refill_required_report_type)
    required_standard = str(args.operator_exact_document_refill_required_standard)
    required_consolidated = bool(args.operator_exact_document_refill_required_consolidated)
    trusted_hosts = _financial_document_fetch_list(workspace.get("trusted_source_hosts"))
    historical_url = str(
        workspace.get("latest_historical_document_url")
        or refill_row.get("READONLY_latest_historical_document_url")
        or ""
    )
    raw_url = str(refill_row.get("operator_fill_exact_document_url") or "").strip()
    parsed = urllib.parse.urlparse(raw_url)
    normalized_url = _normalize_candidate_url(raw_url)
    extension = Path(parsed.path).suffix.casefold()
    title = str(refill_row.get("operator_fill_document_title") or "")
    filled_type = str(refill_row.get("operator_fill_document_report_type") or "")
    filled_standard = str(refill_row.get("operator_fill_document_accounting_standard") or "")
    filled_consolidated_raw = refill_row.get("operator_fill_document_consolidated")
    row_args = _clone_args(
        args,
        report_period=target_period,
        report_type=required_type,
        accounting_standard=required_standard,
        exact_document_allow_prior_year_fallback=False,
    )
    kind = classify_exact_document_kind(normalized_url, title, args=row_args) if normalized_url else ""
    period = classify_exact_document_period(normalized_url, title, "", args=row_args) if normalized_url else {}
    report_type = (
        classify_exact_document_report_type(
            normalized_url,
            title,
            args=row_args,
            period_quarter=str(period.get("document_period_quarter") or ""),
        )
        if normalized_url
        else {}
    )
    standard = classify_exact_document_accounting_standard(normalized_url, title, args=row_args) if normalized_url else {}
    reasons: list[str] = []
    errors: list[str] = []
    warnings: list[str] = []
    identity = str(refill_row.get("workspace_id") or refill_row.get("canonical_company_id") or refill_row.get("company_id") or "")
    workspace_status = str(workspace.get("workspace_status") or refill_row.get("workspace_status") or "")
    requirements_mismatch = _operator_exact_document_refill_validation_requirements_mismatch(
        refill_row,
        workspace,
        target_period=target_period,
        required_type=required_type,
        required_standard=required_standard,
        required_consolidated=required_consolidated,
    )
    host_status = _operator_exact_document_refill_validation_host_status(normalized_url, trusted_hosts)
    historical_status = (
        "historical_fallback_url_not_allowed"
        if normalized_url and _normalize_candidate_url(historical_url) == normalized_url
        else "archive_or_history_url_not_allowed"
        if normalized_url and _source_trust_has_archive_or_history_url([normalized_url])
        else "not_historical_fallback"
    )
    landing_status = _operator_exact_document_refill_validation_landing_status(
        normalized_url,
        title=title,
        kind=kind,
        args=row_args,
    )
    status = "valid_future_exact_document_candidate"
    if not workspace_available or not workspace or context["workspace_ambiguous"]:
        status = "blocked_unknown_readiness"
    elif workspace_status == "blocked_source_trust_required_before_exact_document_refill":
        status = "blocked_source_trust_required"
    elif workspace_status != "ready_for_exact_document_url_refill" or requirements_mismatch:
        status = "blocked_workspace_not_ready"
    elif not raw_url:
        status = "incomplete_missing_exact_document_url"
    elif identity in duplicate_identity_keys or normalized_url in duplicate_urls:
        status = "invalid_duplicate_candidate"
    elif parsed.scheme and parsed.scheme.casefold() not in {"http", "https"}:
        status = "invalid_non_http_url"
    elif not normalized_url:
        status = "invalid_malformed_url"
    elif historical_status == "historical_fallback_url_not_allowed":
        status = "invalid_historical_fallback_url"
    elif historical_status == "archive_or_history_url_not_allowed":
        status = "invalid_archive_or_history_url"
    elif host_status != "trusted_source_host_match":
        status = "invalid_untrusted_host"
    elif landing_status == "landing_page_not_allowed":
        status = "invalid_landing_page_url"
    elif _operator_exact_document_refill_validation_forbidden_type(normalized_url, title, kind=kind):
        status = "invalid_forbidden_document_type"
    elif str(period.get("document_period_status") or "") != "target_period":
        status = "invalid_wrong_period"
    elif (
        (filled_type and filled_type.casefold() != required_type.casefold())
        or str(report_type.get("report_type_match_status") or "") != "annual_match"
    ):
        status = "invalid_wrong_report_type"
    elif (
        (filled_standard and filled_standard.casefold() != required_standard.casefold())
        or str(standard.get("accounting_standard_match_status") or "") != "standard_match"
    ):
        status = "invalid_wrong_standard"
    elif required_consolidated and filled_consolidated_raw is not None and not _as_bool(filled_consolidated_raw):
        status = "invalid_non_consolidated"

    _append_unique(reasons, _operator_exact_document_refill_validation_blocker_code(status))
    if status.startswith("invalid_"):
        errors.append(_operator_exact_document_refill_validation_blocker_code(status))
    if extension in {".xlsx", ".xls", ".zip"}:
        warnings.append("non_pdf_document_requires_future_content_type_check")
    if required_consolidated and filled_consolidated_raw is None:
        warnings.append("consolidated_status_requires_future_strict_validation")
    years = _extract_exact_document_years(_exact_document_evidence_text(normalized_url, title)) if normalized_url else []
    if target_period in years and any(year < target_period for year in years):
        warnings.append("older_period_signal_requires_future_strict_validation")
    validation_id = f"operator_exact_document_refill_validation:{workspace_id or canonical_company_id or company_id}"
    accepted_candidate_id = (
        f"operator_exact_document_refill_candidate:{workspace_id or canonical_company_id or company_id}"
        if status == "valid_future_exact_document_candidate"
        else ""
    )
    return {
        "validation_id": validation_id,
        "workspace_id": workspace_id,
        "company_id": company_id,
        "company_name": company_name,
        "canonical_company_id": canonical_company_id,
        "canonical_company_name": canonical_company_name,
        "target_reporting_period": target_period,
        "required_report_type": required_type,
        "required_standard": required_standard,
        "required_consolidated": required_consolidated,
        "workspace_status": workspace_status,
        "workspace_action": workspace.get("workspace_action") or refill_row.get("workspace_action") or "",
        "source_trust_status": workspace.get("source_trust_status") or "",
        "trusted_source_hosts": sorted(set(trusted_hosts)),
        "current_known_source_page_url": workspace.get("current_known_source_page_url")
        or refill_row.get("READONLY_current_known_source_page_url")
        or "",
        "latest_historical_document_url": historical_url,
        "historical_fallback_allowed_as_target_evidence": False,
        "historical_fallback_allowed_as_trusted_source": False,
        **{field: refill_row.get(field) or "" for field in OPERATOR_EXACT_DOCUMENT_REFILL_TEMPLATE_FIELDS if field.startswith("operator_fill_")},
        "normalized_document_url": normalized_url,
        "document_url_scheme": parsed.scheme.casefold(),
        "document_url_host": _host(normalized_url),
        "document_url_path": parsed.path or "",
        "document_url_file_extension": extension,
        "document_url_registrable_domain": _source_trust_registrable_domain(_host(normalized_url)),
        "validation_status": status,
        "validation_severity": "info" if status == "valid_future_exact_document_candidate" else "warning" if status.startswith(("blocked_", "incomplete_")) else "error",
        "validation_action": _operator_exact_document_refill_validation_action(status),
        "validation_reason_codes": reasons,
        "validation_errors": errors,
        "validation_warnings": list(dict.fromkeys(warnings)),
        "period_validation_status": period.get("document_period_status") or "not_checked",
        "report_type_validation_status": report_type.get("report_type_match_status") or "not_checked",
        "standard_validation_status": standard.get("accounting_standard_match_status") or "not_checked",
        "consolidated_validation_status": (
            "not_required"
            if not required_consolidated
            else "consolidated_match"
            if filled_consolidated_raw is not None and _as_bool(filled_consolidated_raw)
            else "non_consolidated"
            if filled_consolidated_raw is not None
            else "unknown_consolidated_status"
        ),
        "host_validation_status": host_status,
        "url_shape_validation_status": (
            "valid_document_like_url"
            if normalized_url and landing_status != "landing_page_not_allowed"
            else "invalid_document_url_shape"
        ),
        "historical_fallback_validation_status": historical_status,
        "landing_page_validation_status": landing_status,
        "accepted_candidate_id": accepted_candidate_id,
        "accepted_for_future_apply_draft": status == "valid_future_exact_document_candidate",
        "future_strict_validation_required": status == "valid_future_exact_document_candidate",
        "future_download_plan_rerun_required": status == "valid_future_exact_document_candidate",
        "fetch_plan_status": workspace.get("fetch_plan_status") or fetch.get("fetch_plan_status") or "",
        **_operator_exact_document_refill_validation_row_safety_flags(),
    }


def _operator_exact_document_refill_validation_requirements_mismatch(
    refill_row: dict[str, Any],
    workspace: dict[str, Any],
    *,
    target_period: str,
    required_type: str,
    required_standard: str,
    required_consolidated: bool,
) -> bool:
    checks = (
        (refill_row.get("READONLY_target_reporting_period"), target_period),
        (workspace.get("target_reporting_period"), target_period),
        (refill_row.get("READONLY_required_report_type"), required_type),
        (workspace.get("required_report_type"), required_type),
        (refill_row.get("READONLY_required_standard"), required_standard),
        (workspace.get("required_standard"), required_standard),
    )
    if any(value is not None and str(value).casefold() != str(expected).casefold() for value, expected in checks):
        return True
    consolidated_values = (
        refill_row.get("READONLY_required_consolidated"),
        workspace.get("required_consolidated"),
    )
    return any(value is not None and _as_bool(value) != required_consolidated for value in consolidated_values)


def _operator_exact_document_refill_validation_host_status(url: str, trusted_hosts: list[str]) -> str:
    if not url:
        return "not_checked"
    candidate_domain = _source_trust_registrable_domain(_host(url))
    trusted_domains = {_source_trust_registrable_domain(host) for host in trusted_hosts if host}
    return "trusted_source_host_match" if candidate_domain and candidate_domain in trusted_domains else "untrusted_source_host"


def _operator_exact_document_refill_validation_landing_status(
    url: str,
    *,
    title: str,
    kind: str,
    args: argparse.Namespace,
) -> str:
    if not url:
        return "not_checked"
    extension = Path(urllib.parse.urlparse(url).path).suffix.casefold()
    if extension in {".pdf", ".xlsx", ".xls", ".zip"}:
        return "exact_document_url_shape"
    if kind in EXACT_DOCUMENT_CATEGORY_KINDS or _exact_document_is_generic_page(url, title, args):
        return "landing_page_not_allowed"
    return "exact_document_url_shape" if _exact_document_has_strong_signals(url, title, args) else "landing_page_not_allowed"


def _operator_exact_document_refill_validation_forbidden_type(url: str, title: str, *, kind: str) -> bool:
    text = f"{url} {title}".casefold()
    return kind in {
        "presentation_document",
        "prospectus_document",
        "news_or_press_document",
        "legal_policy_document",
        "privacy_policy_document",
        "cookie_policy_document",
        "user_agreement_document",
    } or _contains_any(text, ("sustainability", "esg", "investor deck", "press-release", "press_release"))


def _operator_exact_document_refill_validation_blocker_code(status: str) -> str:
    return {
        "valid_future_exact_document_candidate": "valid_future_exact_document_candidate",
        "incomplete_missing_exact_document_url": "missing_exact_document_url",
        "blocked_source_trust_required": "source_trust_required",
        "blocked_workspace_not_ready": "workspace_not_ready",
        "invalid_malformed_url": "malformed_url",
        "invalid_non_http_url": "non_http_url",
        "invalid_untrusted_host": "untrusted_host",
        "invalid_historical_fallback_url": "historical_fallback_not_allowed",
        "invalid_archive_or_history_url": "archive_or_history_url_not_allowed",
        "invalid_landing_page_url": "landing_page_not_allowed",
        "invalid_wrong_period": "wrong_period",
        "invalid_wrong_report_type": "wrong_report_type",
        "invalid_wrong_standard": "wrong_standard",
        "invalid_non_consolidated": "non_consolidated",
        "invalid_forbidden_document_type": "forbidden_document_type",
        "invalid_duplicate_candidate": "duplicate_candidate",
        "blocked_unknown_readiness": "unknown_readiness",
    }.get(status, "unknown_readiness")


def _operator_exact_document_refill_validation_action(status: str) -> str:
    if status == "valid_future_exact_document_candidate":
        return "review_future_apply_draft_candidate"
    if status == "incomplete_missing_exact_document_url":
        return "fill_exact_target_annual_ifrs_document_url"
    if status == "blocked_source_trust_required":
        return "complete_source_trust_workflow_first"
    return "review_and_correct_operator_input"


